    //Error Messages
  	public void UpdateErrorMessageWithPivotalData(Map<String, String> objDictionary, IOSDriver iosDriver,String strErrorMsg)
  	{
  		HttpConnections clsHttpConnections = new HttpConnections();
		Meter clsMeter = new Meter();
		CommonWeb clsCommonWeb = new CommonWeb();
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		String strTestCase = objDictionary.get("strTestCase");if(strTestCase == null){strTestCase = "";}
  		//Create a request to the Pivotal API to get bug status and assigned to
  		String strPivotalId = "";
  		String strPivotalPath = "";
  		String strRemainParkedShortSession = "True";
  		String strAssociatedBug = objDictionary.get("strAssociatedBug");if(strAssociatedBug == null){strAssociatedBug = "";}
  		String strViolationId = objDictionary.get("strViolationId");if(strViolationId == null){strViolationId = "";}
  		String strMeterId = objDictionary.get("strMeterId");
		//Take ScreenShot
  		if (iosDriver == null){Reporter.log("Unable to take ScreenShot-Android Driver was null");}
  		//Copy Screen Shot Locally
  		clsMeter.METER_CopyMeterScreenShotLocally(objDictionary, strTestCase); 
  		TakeIOSScreenShot(objDictionary,iosDriver,"");
  		strErrorMsg = strErrorMsg.replace("\n", "").trim();  
  		String strHost = objDictionary.get("strHost");
    	String strValidUntilTime = objDictionary.get("strValidUntilTime");
    	String strActualValueUntil = objDictionary.get("strActualValueUntil");
    	String sample = "The Text (Valid until) with index (1) did not equal ("+strValidUntilTime+") - actual value ("+strActualValueUntil+")";
    	boolean sample2 = false;
    	if (sample.equals(strErrorMsg)) {
 //   	String	sample2 = "true";
    	System.out.println("Strings are equal!");
    	}
    	if (strHost != null) 
		{
  			strErrorMsg = clsMeter.METER_CheckForErrorsInMeterLogs(objDictionary, strErrorMsg);
		}
  		switch (strErrorMsg)
   		{	
   			default:
   		}
  		if(!strPivotalId.equals(""))
  		{
  			if(strAssociatedBug.contains(strPivotalId) && !strAssociatedBug.equals("")||strPivotalId.contains(strAssociatedBug) && !strAssociatedBug.equals(""))
  			{
  				objDictionary.put("strAssociatedBug",strPivotalId);
  				Reporter.log("<a style='color:Gold' href=\"https://www.pivotaltracker.com/n/projects/980790/stories/"+strPivotalId+"\" target=\"_blank\">"+strPivotalId+"-"+strErrorMsg+"</a>");
  			}
  			else
  			{Reporter.log("<a style='color:Red' href=\"https://www.pivotaltracker.com/n/projects/980790/stories/"+strPivotalId+"\" target=\"_blank\">"+strPivotalId+"-"+strErrorMsg+"</a>");}
  			iosDriver.quit();
  			//RPSS: Remain Parked Short Session
  	      	if(strRemainParkedShortSession.equals("True")){clsMeter.METER_MeterWaitWithMessage(objDictionary,15, "Error Remain Parked (15) seconds-Spot 1");}
  	      	Assert.fail(strPivotalId+"-"+strErrorMsg);
  		}
  		else
  		{
  			Reporter.log("<font color='red'>"+strErrorMsg+"</font>");
  			if(iosDriver != null){iosDriver.quit();}
  			if(strRemainParkedShortSession.equals("True")){clsMeter.METER_MeterWaitWithMessage(objDictionary,15, "Error Remain Parked (15) seconds-Spot 1");}
  	  	    Assert.fail(strErrorMsg);
  		}
  	}

  	//Connect to iOS
  	public IOSDriver SetMobileDriver(Map<String, String> objDictionary, String strApplication,String strGPSEnabled, String strRole) {
  	    String strMethodName = new Object() {}.getClass().getEnclosingMethod().getName();
  	    // Stop/Start Appium server if requested
  	    String strStopAndStartAppiumServer = objDictionary.getOrDefault("strStopAndStartAppiumServer", "False");
  	    if ("True".equalsIgnoreCase(strStopAndStartAppiumServer)) {
  	        try {Runtime.getRuntime().exec("killall Simulator");} catch (Exception ignored) {}
  	        stopServer(objDictionary);
  	        try {Thread.sleep(2000);} catch (Exception ignored) {}
  	        startServer(objDictionary);
  	        try {Thread.sleep(3000);} catch (Exception ignored) {}
  	    }
  	    String strDeviceAppiumPort = objDictionary.get("strDeviceAppiumPort");
  	    String strEnvironment = objDictionary.get("strEnvironment");
  	    String strIOSDeviceName = objDictionary.getOrDefault("strIOSDeviceName", "iPhone 12");
  	    String strIOSUdid = objDictionary.getOrDefault("strIOSUdid", "");
  	    String strIOSVersion = objDictionary.get("strIOSVersion");
  	    String strUserDir = System.getProperty("user.dir");
  	    // Build .ipa path
  	    String strIOSPath = "";
  	    switch (strEnvironment) {
  	        case "QA":
  	            strIOSPath = strUserDir + "/APP/MPS_Quality_" + strIOSDeviceName + "_" + strIOSVersion + ".ipa";
  	            break;
  	        case "SG":
  	            strIOSPath = strUserDir + "/APP/EasySpotPay_Staging_" + strIOSDeviceName + "_" + strIOSVersion + ".ipa";
  	            break;
  	        case "PROD":
  	            strIOSPath = strUserDir + "/APP/MPS_Production_" + strIOSDeviceName + "_" + strIOSVersion + ".ipa";
  	            break;
  	        default:
  	            break;
  	    }
  	    File f = new File(strIOSPath);
  	    Reporter.log("strIOSPath: " + strIOSPath);
  	    if (!f.exists()) {
  	        UpdateErrorMessageWithPivotalData(objDictionary, null,
  	                "The iOS application path didn't exist (" + strIOSPath + ") - " + strMethodName);
  	        return null;
  	    }

  	    // ====================== XCUITestOptions Setup ======================
  	    XCUITestOptions capabilities = new XCUITestOptions();
  	    capabilities.setPlatformName("iOS");
  	    capabilities.setCapability("appium:automationName", "XCUITest");
  	    capabilities.setCapability("appium:udid", strIOSUdid);
  	    capabilities.setDeviceName(strIOSDeviceName);
  	    // Signing configuration
  	    capabilities.setCapability("appium:xcodeOrgId", "8BRACGA7S9");
  	    capabilities.setCapability("appium:xcodeSigningId", "Apple Development");
  	    capabilities.setCapability("appium:allowProvisioningUpdates", true);
  	    // === Fresh Install Settings (uninstall + reinstall) ===
  	    capabilities.setCapability("appium:app", strIOSPath);           // Use .ipa file
  	    capabilities.setCapability("appium:fullReset", true);           // Uninstalls completely
  	    capabilities.setCapability("appium:noReset", false);
  	    capabilities.setCapability("appium:resetOnSessionStart", true);
  	    capabilities.setCapability("appium:enforceAppInstall", true);   // Force reinstall
  	    capabilities.setShouldTerminateApp(false);                       // Terminate any existing instance
  	    capabilities.setCapability("appium:forceAppLaunch", true);
  	    capabilities.setCapability("appium:useNewWDA", true);           // Fresh WDA for clean install
  	    capabilities.setCapability("appium:clearSystemFiles", true);
  	    // Attach-friendly settings (helps a bit even during fresh launch)
  	    capabilities.setCapability("appium:dontStopAppOnReset", true);
  	    capabilities.setCapability("appium:prebuiltWDA", false);
  	    // Common settings
  	    capabilities.setCapability("appium:newCommandTimeout", 600);
  	    capabilities.setCapability("appium:showXcodeLog", true);
  	    capabilities.setCapability("appium:forceSimulatorSoftwareKeyboardPresence", false);
  	    // Permissions for SG environment
  	    if ("SG".equals(strEnvironment)) {capabilities.setCapability("appium:permissions","{\"com.apple.locationd\":{\"location\":\"inuse\"}}");}
  	    // Device-specific phone number handling
  	    if ("c8be317ecec81cd9b8d06b47bcb575a7f46ced57".equals(strIOSUdid)) {objDictionary.put("strDevicePhone", "16518889153");}

  	    // ====================== Start IOSDriver ======================
  	    IOSDriver iosdriver = null;
  	    try {
  	        Reporter.log("Connecting to Appium on port: " + strDeviceAppiumPort + " (Fresh Install)");
  	        URL appiumUrl = new URL("http://127.0.0.1:" + strDeviceAppiumPort);
  	        iosdriver = new IOSDriver(appiumUrl, capabilities);
  	        Reporter.log("Sentry Mobile loaded correctly on iOS Device (Fresh Install from .ipa)");
  	    } catch (Exception e) {
  	        String errorMsg = "Could not start iOS session. " + e.getMessage();
  	        UpdateErrorMessageWithPivotalData(objDictionary, null, errorMsg + " - " + strMethodName);
  	        e.printStackTrace();
  	    }
  	    if (iosdriver != null) {
  	        System.out.println("Consumer App Loaded Correctly (Fresh Install)");
  	        SENTRYMOBILE_SETGPSSettings(objDictionary, iosdriver, strGPSEnabled, objDictionary.get("strLocation"));
  	        try {
  	            SENTRYMOBILE_CheckUserAccountBalanceAddFundsIfNeeded(objDictionary, strRole);
  	        } catch (Exception ignored) {}
  	    }
  	    return iosdriver;
  	}
  	
