    public void SENTRYMOBILE_ValidateRateBuyMoreTimeMeterPaymentValues(Map<String, String> objDictionary,IOSDriver iosDriver, String strFreeTimeFirstPayment, String strCreditCardIncrementTime, int intPreviousTimePurchased)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		String strMaximumDuration = objDictionary.get("strMaximumDuration");
		clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Choose Parking Duration", "Choose Parking Duration", 1, "Exists", "");
		//Validate Spot
		String strMeterSpotName = objDictionary.get("strMeterSpotName");
		clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Choose Parking Duration", "Spot", 1, "Contains", strMeterSpotName);
		//Validate Vehicle
		String strLicensePlateNumber = objDictionary.get("strLicensePlateNumber");
		clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Choose Parking Duration", "Vehicle", 1, "Contains", strLicensePlateNumber);
		//Validate Max Time
     	clsCommonMobile.VALIDATIONS_MeterPayment_MaxTime(objDictionary, iosDriver, 0, Integer.parseInt(strMaximumDuration), intPreviousTimePurchased);
    }
    public void SENTRYMOBILE_ValidateSubsequentPayment(Map<String, String> objDictionary,IOSDriver iosDriver)
	{
		Meter clsMeter = new Meter();
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		//Validate Subsequent Payment
	    String strMeterNextRateCost = clsMeter.GetMeterNextRateCost(objDictionary);
	 	double dblMeterNextRateCost = Double.parseDouble(strMeterNextRateCost) / 100;
	 	strMeterNextRateCost = "$" + String.format("%.2f", dblMeterNextRateCost);
	 	String strSubsequentPaymentTotal = clsCommonMobile.SENTRYMOBILE_ValidateSubsequentPaymentDialogAndReturnParkingFee(objDictionary, iosDriver, strMeterNextRateCost);
	    //Select Payment Option and Pay
	 	clsCommonMobile.PopulateScrollableListbox(objDictionary,iosDriver, "Review and Pay", "Select Payment Option", "Sentry Mobile Account");
	 	clsCommonMobile.ClickButton(objDictionary, iosDriver, "Review and Pay", "Proceed", 1);
		String strStartTime = objDictionary.get("strParkingSessionStart");//SENTRYMOBILE_PurchaseMeterTimeParkThenPay
		String strMeterIncrementTime = objDictionary.get("strMeterIncrementTime");
		int intPurchasedTime = Integer.parseInt(strMeterIncrementTime) * 2;
		String strEndTime = clsCommonMobile.AddTimeToExistingTime(strStartTime, Integer.toString(intPurchasedTime),"MMM dd, hh:mm a");
		String strFreeTimeFirstPayment = objDictionary.get("strFreeTimeFirstPayment");
		//Add Free Time to End Time
  		if (!strFreeTimeFirstPayment.equals("")){strEndTime = clsCommonMobile.AddTimeToExistingTime(strEndTime, strFreeTimeFirstPayment,"MMM dd, hh:mm a");}
  		//Might want to pass this in.
	    String strCurrentMeterTime = "15";
	    String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
	    String strTrueUpStartTime = objDictionary.get("strTrueUpStartTime");if(strTrueUpStartTime == null){strTrueUpStartTime = "";}
	    String strSessionReset = objDictionary.get("strSessionReset");if(strSessionReset == null){strSessionReset = "False";}
	    String strIncludePayment = objDictionary.get("strIncludePayment");if(strIncludePayment == null){strIncludePayment = "False";}
	    String strTrueUp = objDictionary.get("strTrueUp");if(strTrueUp == null){strTrueUp = "False";}
		String strViolationBonusPaymentAmount = objDictionary.get("strViolationBonusPaymentAmount");
		//Wait For Parking Session Details
		clsCommonMobile.GlobalWait(objDictionary, iosDriver, "Parking Sessions", "{TextExists} Parking Sessions~Parking Session Details", 80);
	 	//Calculate MeterRemainingTimeMinutes
		int intMeterRemainingTimeMinutes = 0;
		//Update with True-Up
		if(strTrueUpStartTime.equals("")||strSessionReset.equals("True"))
		{
			intMeterRemainingTimeMinutes = Integer.parseInt(strMeterIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strMeterIncrementTime);
			if(strIncludePayment.equals("True"))
			{
				String strViolationBonusPaymentTime = objDictionary.get("strViolationBonusPaymentTime");
				int intUsedTime = 0;
				if(strTrueUp.equals("True")){intUsedTime = clsMeter.METER_CalculateUsedTime(objDictionary, null, strViolationBonusPaymentTime);}
					if(strViolationBonusPaymentAmount != null)
					{
						if(strSessionReset.equals("True"))
						{
							intMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + (Integer.parseInt(strViolationBonusPaymentAmount)/25 * Integer.parseInt(strMeterIncrementTime));
						}
						else
						{
							intMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + (Integer.parseInt(strViolationBonusPaymentAmount)/25 * Integer.parseInt(strMeterIncrementTime)) -intUsedTime;
						}
					}
					Reporter.log("***********Parking Time After Violation Reset With Payment*************");
						clsMeter.SENTRYMETER_StoreParkingSessionTime(objDictionary);
						Reporter.log("***********Parking Time After Violation Reset With Payment*************");
				}
				String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");if(strFreeTimeMinutes == null) {strFreeTimeMinutes = "0";}
				if(!strFreeTimeMinutes.equals("0"))
				{
					if(strRemainingFreeTimeStart != null)
					{
						//Free To Rate
						int intRemainingFreeTimeMinutes = clsMeter.METER_CalculateRemainingFreeTime(objDictionary, null, strRemainingFreeTimeStart, strFreeTimeMinutes);
						intMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + intRemainingFreeTimeMinutes;
						objDictionary.put("strRemainingFreeTimeMinutes", Integer.toString(intRemainingFreeTimeMinutes));
						strEndTime = clsCommonMobile.AddTimeToExistingTime(strStartTime, String.valueOf(intMeterRemainingTimeMinutes),"MMM dd, hh:mm a");
						System.out.println("MIH");
					}
					else
					{
						String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
						intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null, strMinutesBeforeFreeStart);
						if(intMeterRemainingTimeMinutes > (Integer.parseInt(strMeterIncrementTime) * 2))
						{
							intMeterRemainingTimeMinutes = Integer.parseInt(strMeterIncrementTime) * 2;
						}
						strEndTime = clsCommonMobile.AddTimeToExistingTime(strStartTime, String.valueOf(intMeterRemainingTimeMinutes),"MMM dd, hh:mm a");
						objDictionary.put("strMeterRemainingTimeMinutes", Integer.toString(intMeterRemainingTimeMinutes));
					}
			  	}
			}
			else
			{
				intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingTrueUpTime(objDictionary, null,  strTrueUpStartTime, strMeterIncrementTime) + Integer.parseInt(strMeterIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment);
			}
			//Validate Expected Meter Time
			clsMeter.METER_ValidateExpectedMeterTime(objDictionary, null, intMeterRemainingTimeMinutes, "1");
			//ValidateParkingSession
			String strFirstPaymentFee = objDictionary.get("strFirstPaymentFee");//SENTRYMOBILE_PurchaseMeterTimeParkThenPay
			String strSecondPaymentFee = objDictionary.get("strTotalFee");//SENTRYMOBILE_ValidateFirstPaymentDialogAndReturnParkingFee
			double dblFirstPaymentFee = Double.parseDouble(strFirstPaymentFee.replace("$", "").trim());
			double dblSecondPaymentFee = Double.parseDouble(strSecondPaymentFee.replace("$", "").trim());
			double dblTotalPayment = dblFirstPaymentFee + dblSecondPaymentFee;
			//Wait For Parking Session Details
        	clsCommonMobile.GlobalWait(objDictionary, iosDriver, "Parking Sessions", "{TextExists} Parking Sessions~Parking Session Details", 80);
         	//Work Around For a Bug
        	clsCommonMobile.ClickButton(objDictionary, iosDriver, "Parking Sessions", "History", 1);
        	clsCommonMobile.ClickButton(objDictionary, iosDriver, "Parking Sessions", "Active", 1);
        	//Subtract a minuted for used time
        	String strActualRemainingTimeMinutes = objDictionary.get("strActualRemainingTimeMinutes");
        	int intActualRemainingTimeMinutes = Integer.parseInt(strActualRemainingTimeMinutes);
        	objDictionary.put("strActualRemainingTimeMinutes",String.valueOf(intActualRemainingTimeMinutes));
        	//ValidateParkingSession
			clsCommonMobile.SENTRYMOBILE_ValidateParkingSession(objDictionary,iosDriver,strStartTime, strEndTime, String.format("$ %.2f", dblTotalPayment));
	}
    
    //**********************
  	//Application Validations
  	//**********************
    public String SENTRYMOBILE_ValidateSubsequentPaymentDialogAndReturnParkingFee(Map<String, String> objDictionary,IOSDriver iosDriver, String strTotalFee)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		HttpConnections clsHttpConnections = new HttpConnections();
		//Get Fees At Time of Purchase
		try {clsHttpConnections.HTTPCONNECTIONS_StoreMobileTransactionFees(objDictionary);}catch (Exception e) {}
		String strMeterSpotName = objDictionary.get("strMeterSpotName");
		clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Spot", 1, "Contains", strMeterSpotName);
		String strSubsequentPayment = objDictionary.get("strSubsequentPayment");
		if(strSubsequentPayment == null){strSubsequentPayment = "0";}
		String strParkingFee = strTotalFee;
		DecimalFormat dFormat = new DecimalFormat("$ 0.00");
		if(strSubsequentPayment.equals("0"))
		{
			double dblParkingFee = Double.parseDouble(strParkingFee.replace("$",""));
			double dblConvenienceFee = Double.parseDouble(strSubsequentPayment)*.01;
			double dblTotalFee = dblParkingFee + dblConvenienceFee;
			strParkingFee = dFormat.format(dblParkingFee);
			VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Parking Fee", 1, "Contains", dFormat.format(dblParkingFee));
			VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Total Fee", 1, "Contains", dFormat.format(dblTotalFee));
			return String.valueOf(dFormat.format(dblTotalFee));
		}
		else
		{
			double dblParkingFee = Double.parseDouble(strParkingFee.replace("$",""));
			double dblConvenienceFee = Double.parseDouble(strSubsequentPayment)*.01;
			double dblTotalFee = dblParkingFee + dblConvenienceFee;
			strParkingFee = dFormat.format(dblParkingFee);
			VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Parking Fee", 1, "Contains", dFormat.format(dblParkingFee));
			VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Convenience Fee", 1, "Contains", dFormat.format(dblConvenienceFee));
			VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Total Fee", 1, "Contains", dFormat.format(dblTotalFee));
			objDictionary.put("strTotalFee", dFormat.format(dblTotalFee));
			return String.valueOf(dFormat.format(dblTotalFee));
		}
	}
    
