//    //COMMON SENTRYMOBILE FUNCTIONS
    public void SENTRYMOBILE_SetGPSCoordinates(double latitude, double longitude)
	{
	    try
	    {
	        String simulatorName = simulatorAppName();   // Make sure this method returns "Simulator" or "iOS Simulator"
	
	        String[] cmd = {
	            "osascript", "-e",
	            "application \"" + simulatorName + "\" activate\n" +
	            "delay 0.5\n" +
	            "tell application \"System Events\"\n" +
	            "    tell process \"" + simulatorName + "\"\n" +
	            "        click menu item \"None\" of menu \"Location\" of menu item \"Debug\" of menu bar 1\n" +
	            "        delay 0.5\n" +
	            "        click menu item \"Custom Location…\" of menu \"Location\" of menu item \"Debug\" of menu bar 1\n" +
	            "        delay 0.5\n" +
	            "        set value of text field 1 of window \"Custom Location\" to \"" + latitude + "\"\n" +
	            "        set value of text field 2 of window \"Custom Location\" to \"" + longitude + "\"\n" +
	            "        click button \"OK\" of window \"Custom Location\"\n" +
	            "    end tell\n" +
	            "end tell"
	        };
	
	        Process process = Runtime.getRuntime().exec(cmd);
	
	        // Print any script errors
	        try (BufferedReader br = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
	            String line;
	            while ((line = br.readLine()) != null) {
	                System.out.println("osascript error: " + line);
	            }
	        }
	
	        Thread.sleep(4000);   // Give Simulator time to apply the location
	        System.out.println("GPS set to: " + latitude + ", " + longitude);
	    }
	    catch (Exception e)
	    {
	        System.out.println("Failed to set GPS coordinates: " + e.getMessage());
	        e.printStackTrace();
	    }
	}
