	private static final String SENTRY_MOBILE_IOS_BUNDLE = "com.mpspark.consumer.MPS";
	private void iosGpsSleep(long millis) {
		try {
			Thread.sleep(millis);
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
		} catch (Exception ignored) {
		}
	}
	
	private void iosOpenSettingsFromHome(IOSDriver iosDriver) {
		try {
			iosDriver.findElement(By.xpath("(//XCUIElementTypeIcon[@name=\"Settings\"])[2]")).click();
			Reporter.log("Device (Settings) was clicked successfully");
		} catch (Exception e) 
		{
//			IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
//			clsCommonMobile.ClickPermissionAlertButton(null, iosDriver, "Allow While Using App");
			iosDriver.findElement(By.id("Settings")).click();
		}
	}

	private void iosNavigateSettingsToPrivacyLocation(Map<String, String> objDictionary, IOSDriver iosdriver) throws Exception {
		String strCondition = ConditionalStepTextField(objDictionary, iosdriver, "iOS Settings", "Search", 1, "Exists", "");
		if (strCondition.equals("False")) {
			SwipeDown(iosdriver);
			iosGpsSleep(1000);
			SwipeDown(iosdriver);
		}
		WebElement search = GetTextFieldObj(objDictionary, iosdriver, "iOS Settings", "Search");
		search.clear();
		search.sendKeys("Privacy & Security");
		iosGpsSleep(4000);
		iosdriver.findElement(By.xpath("//XCUIElementTypeButton[@name=\"Privacy & Security\"]")).click();
		iosGpsSleep(3000);
		iosdriver.findElement(By.xpath("//XCUIElementTypeButton[@name=\"LOCATION\"]")).click();
		iosGpsSleep(2000);
	}

	private WebElement iosLocationServicesMasterRow(IOSDriver iosdriver) {
		List<WebElement> rows = iosdriver.findElements(By.id("Location Services"));
		if (rows.isEmpty()) {
			return null;
		}
		return rows.get(rows.size() - 1);
	}
	private void iosEnableLocationServicesMaster(IOSDriver iosdriver) {
		WebElement row = iosLocationServicesMasterRow(iosdriver);
		if (row == null) {
			return;
		}
		if ("0".equals(row.getText())) {
			row.click();
			Reporter.log("Location Services was enabled");
			iosGpsSleep(2000);
		}
	}
	private void iosDisableLocationServicesMaster(IOSDriver iosdriver) {
		WebElement row = iosLocationServicesMasterRow(iosdriver);
		if (row == null) {
			return;
		}
		if ("1".equals(row.getText())) {
			row.click();
			Reporter.log("Location Services was disabled");
			iosGpsSleep(2000);
			iosdriver.findElement(By.id("Turn Off")).click();
			Reporter.log("Turn off link was clicked");
		}
	}
	private void iosReturnToSentryMobile(IOSDriver iosdriver) {
		iosdriver.runAppInBackground(Duration.ofSeconds(-1));
		iosdriver.activateApp(SENTRY_MOBILE_IOS_BUNDLE);
	}
	/**
	 * Toggles the system Location Services master switch on a physical device via Settings UI.
	 * Retries if we are already on the Location Services screen (navigation from home fails).
	 */
	private void iosSetLocationServicesMasterOnDevice(Map<String, String> objDictionary, IOSDriver iosdriver, boolean enable) {
		iosdriver.runAppInBackground(Duration.ofSeconds(-1));
		iosGpsSleep(1000);
		iosOpenSettingsFromHome(iosdriver);
		try {
			iosNavigateSettingsToPrivacyLocation(objDictionary, iosdriver);
			if (enable) {
				iosEnableLocationServicesMaster(iosdriver);
			} else {
				iosDisableLocationServicesMaster(iosdriver);
				System.out.println("MIH");
			}
			iosReturnToSentryMobile(iosdriver);
		} catch (Exception ignored) {
			try {
				if (!enable) {
					iosGpsSleep(1000);
				}
				if (enable) {
					iosEnableLocationServicesMaster(iosdriver);
				} else {
					iosDisableLocationServicesMaster(iosdriver);
				}
				iosReturnToSentryMobile(iosdriver);
			} catch (Exception ignored2) {
				try {
					WebElement row = iosLocationServicesMasterRow(iosdriver);
					if (row == null) {
						System.out.println("MIH");
						return;
					}
					String val = row.getText();
					if (enable) {
						if ("0".equals(val)) {
							row.click();
							Reporter.log("Location Services was enabled");
							iosGpsSleep(2000);
						} else {
							Reporter.log("Location Services was already disabled");
						}
					} else {
						if ("1".equals(val)) {
							row.click();
							Reporter.log("Location Services was disabled");
							iosGpsSleep(2000);
							iosdriver.findElement(By.id("Turn Off")).click();
							Reporter.log("Turn off link was clicked");
						} else {
							Reporter.log("Location Services was already disabled");
						}
					}
					iosReturnToSentryMobile(iosdriver);
				} catch (Exception ignored3) {
					System.out.println("MIH");
				}
			}
		}
	}
