	public void SENTRYMOBILE_Open(Map<String, String> objDictionary, IOSDriver iosDriver)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		//APNS received Notification
		try{iosDriver.findElement(By.name("OK")).click();}catch (Exception e) {}
		String strCondition = clsCommonMobile.ConditionalStepButton(objDictionary, iosDriver, "User Agreement", "OK", 1, "Exists", "");
		if(strCondition.equals("True"))
		{
			clsCommonMobile.ClickButton(objDictionary, iosDriver, "User Agreement", "OK",1);
		}
		strCondition = clsCommonMobile.ConditionalStepButton(objDictionary, iosDriver, "User Agreement", "Remind me later", 1, "Exists", "");
		if(strCondition.equals("True"))
		{
			clsCommonMobile.ClickButton(objDictionary, iosDriver, "User Agreement", "Remind me later",1);
			clsCommonMobile.ClickButton(objDictionary, iosDriver, "User Agreement", "OK",1);
		}
		clsCommonMobile.ClickButton(objDictionary, iosDriver, "User Agreement", "Accept",1);
	}
	
