	public void SENTRYMOBILE_Populate_MeterPayment_SelectSpot(Map<String, String> objDictionary,IOSDriver iosDriver, String strSpotNumber)
  	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		CommonWeb clsCommonWeb = new CommonWeb();
		Meter clsMeter = new Meter();
  		String strDeviceId = objDictionary.get("strDeviceId");
		String[] arrMeterSpots = strDeviceId.split("-");
		String strMeterSpotName = "";
		if(strSpotNumber.equals("1")){strMeterSpotName = arrMeterSpots[0];}else{strMeterSpotName = arrMeterSpots[1];}
		//Navigate to Account
		clsCommonMobile.SENTRYMOBILE_NavigateToPageUsingMenuButtons(objDictionary,iosDriver, "Park");
		clsCommonMobile.PopulateAction(objDictionary, iosDriver, "Enter your Parking Zone Number", "Populate Zone Number", "{T} Zone Number",strMeterSpotName);
		objDictionary.put("strMeterSpotName", strMeterSpotName);
		clsCommonMobile.ClickButton(objDictionary, iosDriver,  "Enter your Parking Zone Number", "Meter Spot Number", 1);
		String strSnackbarText = objDictionary.get("strSnackbarText");if(strSnackbarText == null) {strSnackbarText = "";}
		if(strSnackbarText.equals("Failed to fetch possible rates for the spot."))
		{UpdateErrorMessageWithPivotalData(objDictionary, iosDriver, "The snackbar message: Failed to fetch possible rates for the spot. appeared after click Meter Spot");}
		// Convert string to integer
        String strMaximumDuration = objDictionary.get("strMaximumDuration");
        String strTimePurchased = objDictionary.get("strTimePurchased"); if(strTimePurchased == null) {strTimePurchased = "0";}
        int intRemainingMinutes = Integer.parseInt(strMaximumDuration) - Integer.parseInt(strTimePurchased);
        String strMeterIncrementTime = objDictionary.get("strMeterIncrementTime");
        // Round up to the next hour
        int intHours = intRemainingMinutes / 60;
        int intMinutes = intRemainingMinutes % 60;
        String strExpectedSpotDetails = "";
        String strExpectedSpotDetailsFreeTimePlus1 = "";
        String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");if(strFreeTimeMinutes == null) {strFreeTimeMinutes = "0";}
        if(strFreeTimeMinutes.equals("0"))//Rate
        {
	        if(intMinutes == 0)
	        {strExpectedSpotDetails = strMeterSpotName+" Time Limit "+intHours+"hr Rate $ 0.25 / "+strMeterIncrementTime+" minutes Hours of Enforcement 12:00 am-11:59 pm";}
	        else
	        {strExpectedSpotDetails = strMeterSpotName+" Time Limit "+intHours+"hr "+intMinutes+" m Rate$ 0.25 / "+strMeterIncrementTime+" minutesHours of Enforcement12:00 am-11:59 pm";}
	        clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Enter your Parking Zone Number", "Spot Details",1, "Value",strExpectedSpotDetails);
        }
        else
        {
        	//Get Remaining Free Time
        	String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
        	if(strRemainingFreeTimeStart != null)
        	{
        		//Free To Rate
	        	int intRemainingFreeMinutes = clsMeter.METER_CalculateRemainingFreeTimeCeil(objDictionary, null,  strRemainingFreeTimeStart, strFreeTimeMinutes);
	    		int intRemainingFreeMinutesPlus1 = clsMeter.METER_CalculateRemainingFreeTimeCeil(objDictionary, null,  strRemainingFreeTimeStart, strFreeTimeMinutes) + 1;
	    		Reporter.log("intRemainingFreeMinutes: "+intRemainingFreeMinutes+"-"+strMethondName);
	    		Reporter.log("intRemainingFreeMinutesPlus1: "+intRemainingFreeMinutesPlus1+"-"+strMethondName);
	    		String strFreeParkingUntilTime = clsCommonWeb.AddTimeToCurrentTime(String.valueOf(intRemainingFreeMinutes),"h:mm a");
	    		String strFreeParkingUntilTimePlus1 = clsCommonWeb.AddTimeToCurrentTime(String.valueOf(intRemainingFreeMinutesPlus1),"h:mm a");
	  			if(intMinutes == 0)
	 	        {
	    			strExpectedSpotDetails = strMeterSpotName+" Free parking until "+strFreeParkingUntilTime+" Time Limit  "+intHours+"h Rate $ 0.25 / "+strMeterIncrementTime+" minutes Hours of Enforcement "+strFreeParkingUntilTime.toLowerCase()+"-11:59 pm";
	    			strExpectedSpotDetailsFreeTimePlus1 = strMeterSpotName+" Free parking until "+strFreeParkingUntilTimePlus1+" Time Limit  "+intHours+"h Rate $ 0.25 / "+strMeterIncrementTime+" minutes Hours of Enforcement "+strFreeParkingUntilTimePlus1.toLowerCase()+"-11:59 pm";
	 	        }
	 	        else
	 	        {
	 	        	//Not Updated
	 	        	strExpectedSpotDetails = strMeterSpotName+"Time Limit "+intHours+"h "+intMinutes+"mRate$ 0.25 / "+strMeterIncrementTime+" minutesHours of Enforcement12:00 am-11:59 pm";
	 	        }
	    		String strSpotDetails = clsCommonMobile.StoreText(objDictionary, iosDriver, "Enter your Parking Zone Number", "Spot Details", 1, "strSpotDetails");
	    		if(strSpotDetails.contains(strExpectedSpotDetails))
	    		{Reporter.log("The Text (Spot Details) with index (1) contained (" + strExpectedSpotDetails + ")");}
	    		else if(strSpotDetails.contains(strExpectedSpotDetailsFreeTimePlus1))
	    		{Reporter.log("The Text (Spot Details) with index (1) contained (" + strExpectedSpotDetailsFreeTimePlus1 + ")");}
	    		else
	    		{
	    			//UpdateErrorMessageWithPivotalData(objDictionary, androidDriver, "The Text (Spot Details) with index (1) did not contain (" + strExpectedSpotDetails + ") - actual value (" + strSpotDetails + ")");
	    			System.out.println("MIH");
	    		}
        	}
        	else
        	{
        		//Rate To Free
        		String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
        		String strExpectedSpotDetailsRemainingTimeMinus1 = "";
            	if(strMinutesBeforeFreeStart != null)
            	{
            		int intRemainingMinutesBeforeFree = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null, strMinutesBeforeFreeStart);
            		int intRemainingMinutesBeforeFreeMinus1 = intRemainingMinutesBeforeFree -1;
            		int intRemainingMinutesBeforeFreePlus1 = intRemainingMinutesBeforeFree +1;
            		//Calculate Free Parking Start Time
            		String strFreeParkingStartTime = clsCommonWeb.AddTimeToCurrentTime(String.valueOf(intRemainingMinutesBeforeFree),"h:mm a");
    	    		String strFreeParkingStartTimeMinus1 = clsCommonWeb.AddTimeToCurrentTime(String.valueOf(intRemainingMinutesBeforeFreeMinus1),"h:mm a");
    	  			String strFreeParkingStartTimeTimePlus1 = clsCommonWeb.AddTimeToCurrentTime(String.valueOf(intRemainingMinutesBeforeFreePlus1),"h:mm a");
    	  			if(intMinutes == 0)
    	 	        {
    	    			strExpectedSpotDetails = strMeterSpotName+" Free parking starts at "+strFreeParkingStartTime+" Time Limit  "+intRemainingMinutesBeforeFree+"m Rate $ 0.25 / "+strMeterIncrementTime+" minutes Hours of Enforcement 12:00 am-"+strFreeParkingStartTimeMinus1.toLowerCase();
    	    			strExpectedSpotDetailsRemainingTimeMinus1 = strMeterSpotName+" Free parking starts at "+strFreeParkingStartTime+" Time Limit  "+intRemainingMinutesBeforeFreeMinus1+"m Rate $ 0.25 / "+strMeterIncrementTime+" minutes Hours of Enforcement 12:00 am-"+strFreeParkingStartTimeMinus1.toLowerCase();
    	    			strExpectedSpotDetailsFreeTimePlus1 =  strMeterSpotName+" Free parking starts at "+strFreeParkingStartTimeTimePlus1+" Time Limit  "+intRemainingMinutesBeforeFree+"m Rate $ 0.25 / "+strMeterIncrementTime+" minutes Hours of Enforcement 12:00 am-"+strFreeParkingStartTime.toLowerCase();
    	 	        }
    	 	        else
    	 	        {
    	 	        	//Not Updated
    	 	        	strExpectedSpotDetails = strMeterSpotName+"Time Limit "+intHours+"h "+intMinutes+"mRate$ 0.25 / "+strMeterIncrementTime+" minutesHours of Enforcement12:00 am-11:59 pm";
    	 	        }
    	    		String strSpotDetails = clsCommonMobile.StoreText(objDictionary, iosDriver, "Enter your Parking Zone Number", "Spot Details", 1, "strSpotDetails");
    	    		if(strSpotDetails.contains(strExpectedSpotDetails))
    	    		{Reporter.log("The Text (Spot Details) with index (1) contained (" + strExpectedSpotDetails + ")");}
    	    		else if(strSpotDetails.contains(strExpectedSpotDetailsRemainingTimeMinus1))
    	    		{Reporter.log("The Text (Spot Details) with index (1) contained (" + strExpectedSpotDetailsRemainingTimeMinus1 + ")");}
    	    		else if(strSpotDetails.contains(strExpectedSpotDetailsFreeTimePlus1))
    	    		{Reporter.log("The Text (Spot Details) with index (1) contained (" + strExpectedSpotDetailsFreeTimePlus1 + ")");}
    	    		else
    	    		{
    	    			//UpdateErrorMessageWithPivotalData(objDictionary, androidDriver, "The Text (Spot Details) with index (1) did not contain (" + strExpectedSpotDetails + ") - actual value (" + strSpotDetails + ")");
    	    			System.out.println("MIH");
    	    		}
            		
            	}
        	}
        }
        clsCommonMobile.ClickButton(objDictionary, iosDriver, "Enter your Parking Zone Number", "Pay", 1);
	}
	
	public void SENTRYMOBILE_PurchaseMeterTimeParkThenPay(Map<String, String> objDictionary,IOSDriver iosDriver, String strFreeTimeFirstPayment, String strMeterIncrementTime, String strGPSEnabled, String strAlreadyParked)
    {	
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
		Meter clsMeter = new Meter();
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		HttpConnections clsHttpConnections = new HttpConnections();
		String strAndroidUdid = objDictionary.get("strAndroidUdid");
		if(strAndroidUdid == null){strAndroidUdid = "";}
		String strSessionReset = objDictionary.get("strSessionReset");if(strSessionReset == null){strSessionReset = "False";}
		String strIncludePayment = objDictionary.get("strIncludePayment");if(strIncludePayment == null){strIncludePayment = "False";}
		String strMaximumDuration = objDictionary.get("strMaximumDuration");
		String strCurrentMeterTime = objDictionary.get("strCurrentMeterTime");if(strCurrentMeterTime == null){strCurrentMeterTime = "0";}
		String strVirtualMeter = objDictionary.get("strVirtualMeter");if(strVirtualMeter == null){strVirtualMeter = "False";}
		String strUnlockValue = objDictionary.get("strUnlockValue");if(strUnlockValue == null){strUnlockValue = "Off";}
		String strTrueUpStartTime = objDictionary.get("strTrueUpStartTime");if(strTrueUpStartTime == null){strTrueUpStartTime = "";}
		String strTrueUp = objDictionary.get("strTrueUp");if(strTrueUp == null){strTrueUp = "False";}
		String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
	    //PS1: Park Spot 1
	    String strPayByPlate = objDictionary.get("strPayByPlate");if(strPayByPlate == null){strPayByPlate = "False";}
	    String strLicensePlateNumber = objDictionary.get("strLicensePlateNumber");
		String strLicensePlateState = objDictionary.get("strLicensePlateState");
	    if(strAlreadyParked.equals("False"))
	    {
	    	if(strPayByPlate.equals("True"))
	    	{
				//This isn't working
				clsMeter.METER_ParkSpotWithLicensePlate(objDictionary, strLicensePlateNumber);
				//Navigate to Parking Session and enter License Plate
				CommonWeb clsCommonWeb = new CommonWeb();
				clsCommonWeb.AddLicensePlateToParkingSession(objDictionary,strLicensePlateNumber,strLicensePlateState);
			}
	    	else
	    	{clsMeter.METER_ParkSpot(objDictionary,"1","Local");}
	    }
	    clsCommonMobile.SENTRYMOBILE_Populate_MeterPayment_SelectSpot(objDictionary,iosDriver,"1");
	  	clsCommonMobile.SENTRYMOBILE_AddOrSelectLicensePlate(objDictionary, iosDriver, strLicensePlateNumber, strLicensePlateState);
     	String strGracePeriodViolationTime = objDictionary.get("strGracePeriodViolationTime");
     	int intMaximumDuration = Integer.parseInt(strMaximumDuration);
     	String strTrueUpEnabled = clsMeter.METER_Get_PARKING_TRUEUP_ENABLED(objDictionary,null, "Local");
     	//Used for TUOFF_UON
     	String strViolationBonusPaymentAmount = objDictionary.get("strViolationBonusPaymentAmount");
     	if(strViolationBonusPaymentAmount != null)
     	{
     		intMaximumDuration = intMaximumDuration - (Integer.parseInt(strViolationBonusPaymentAmount)/25 * Integer.parseInt(strMeterIncrementTime))-Integer.parseInt(strFreeTimeFirstPayment);
     	}
//     	else if(strGracePeriodViolationTime != null && strTrueUpEnabled.equals("True"))
//     	{
//     		int intTimeUsed = clsMeter.METER_CalculateUsedTime(objDictionary,null,strGracePeriodViolationTime);
//     		intMaximumDuration = Integer.parseInt(strMaximumDuration) - intTimeUsed;
//     	}
     	//Validate Max Time
     	clsCommonMobile.VALIDATIONS_MeterPayment_MaxTime(objDictionary, iosDriver, 0, intMaximumDuration,0);
     	
     	//Just a Test (Need to add test around this)
//     	String strInitialGracePeriod = objDictionary.get("strInitialGracePeriod");
//     	int intInitialGracePeriod = Integer.parseInt(strInitialGracePeriod) * 60;
//     	intInitialGracePeriod = intInitialGracePeriod-60;
//		//Wait for Meter to Violate
//		clsMeter.METER_MeterWaitWithMessage(objDictionary,intInitialGracePeriod, "Waiting for grace period violation-Spot");
     	
     	clsCommonMobile.ClickButton(objDictionary, iosDriver, "Choose Parking Duration", "Proceed", 1);
     	//Validate First Payment Dialog
     	String strMeterNextRateCost = clsMeter.GetMeterNextRateCost(objDictionary);
     	double dblMeterNextRateCost = Double.parseDouble(strMeterNextRateCost) / 100;
     	strMeterNextRateCost = "$" + String.format("%.2f", dblMeterNextRateCost);
     	clsCommonMobile.SENTRYMOBILE_ValidateFirstPaymentDialogAndReturnParkingFee(objDictionary, iosDriver, strMeterNextRateCost,"1");
     	//Select Payment Option and Pay
     	clsCommonMobile.PopulateScrollableListbox(objDictionary,iosDriver, "Review and Pay", "Select Payment Option", "Sentry Mobile Account");
     	clsCommonMobile.ClickButton(objDictionary, iosDriver, "Review and Pay", "Proceed", 1);
     	//Set Start and End Times
     	SimpleDateFormat sdf = new SimpleDateFormat("MMM dd, hh:mm a");
  		String strStartTime = sdf.format(Date.from(Instant.now().truncatedTo(ChronoUnit.MINUTES)));
  		String strEndTime = clsCommonMobile.AddTimeToExistingTime(strStartTime, strMeterIncrementTime,"MMM dd, hh:mm a");
  		//Copy Parking Session results to results
  		String strFirstPaymentTime = objDictionary.get("strFirstPaymentTime");
  		if(strFirstPaymentTime == null)
		{
			try {clsHttpConnections.ReportJsonParkingSessionInformation(objDictionary);}catch (Exception e) {}
			String strJsonParkedAtTimeStamp =  objDictionary.get("strJsonParkedAtTimeStamp");
			Reporter.log("strFirstPaymentTime: "+strJsonParkedAtTimeStamp);
			objDictionary.remove("strFirstPaymentTime");objDictionary.put("strFirstPaymentTime",strJsonParkedAtTimeStamp);
		}
		else
		{
			try {clsHttpConnections.ReportJsonParkingSessionInformation(objDictionary);}catch (Exception e) {}
			String strJsonParkedAtTimeStamp =  objDictionary.get("strJsonParkedAtTimeStamp");
			Reporter.log("strSubsequentPaymentTime: "+strJsonParkedAtTimeStamp);
			objDictionary.remove("strSubsequentPaymentTime");objDictionary.put("strSubsequentPaymentTime",strJsonParkedAtTimeStamp);
		}
  		//Add Free Time to End Time
  		if (!strFreeTimeFirstPayment.equals("")){strEndTime = clsCommonMobile.AddTimeToExistingTime(strEndTime, strFreeTimeFirstPayment,"MMM dd, hh:mm a");}
  		//Wait For Parking Session Details
    	clsCommonMobile.GlobalWait(objDictionary, iosDriver, "Parking Sessions", "{TextExists} Parking Sessions~Parking Session Details", 80);
     	//Calculate MeterRemainingTimeMinutes
		int intCurrentMeterTime = 0;
		if(!strCurrentMeterTime.equals("0") && strRemainingFreeTimeStart != null){intCurrentMeterTime = clsMeter.METER_CalculateRemainingFreeTime(objDictionary, null, strRemainingFreeTimeStart, strCurrentMeterTime);}
		else{intCurrentMeterTime = Integer.parseInt(strCurrentMeterTime);}
		int intMeterRemainingTimeMinutes = 0;
		//Update with True-Up
		if(strTrueUpStartTime.equals("")||strSessionReset.equals("True"))
		{
			intMeterRemainingTimeMinutes = Integer.parseInt(strMeterIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment) + intCurrentMeterTime;
			if(strIncludePayment.equals("True"))
			{
				String strViolationBonusPaymentTime = objDictionary.get("strViolationBonusPaymentTime");
				int intUsedTime = 0;
				if(strTrueUp.equals("True")){intUsedTime = clsMeter.METER_CalculateUsedTime(objDictionary, null, strViolationBonusPaymentTime);}
				if(strViolationBonusPaymentAmount != null)
				{
					if(strSessionReset.equals("True"))
					{
						intMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + (Integer.parseInt(strViolationBonusPaymentAmount)/25 * Integer.parseInt(strMeterIncrementTime));
					}
					else
					{
						intMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + (Integer.parseInt(strViolationBonusPaymentAmount)/25 * Integer.parseInt(strMeterIncrementTime)) -intUsedTime;
					}
				}
				Reporter.log("***********Parking Time After Violation Reset With Payment*************");
  				clsMeter.SENTRYMETER_StoreParkingSessionTime(objDictionary);
  				Reporter.log("***********Parking Time After Violation Reset With Payment*************");
			}
			String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");if(strFreeTimeMinutes == null) {strFreeTimeMinutes = "0";}
			if(!strFreeTimeMinutes.equals("0"))
			{
				if(strRemainingFreeTimeStart != null)
				{
					int intRemainingFreeTimeMinutes = clsMeter.METER_CalculateRemainingFreeTime(objDictionary, null, strRemainingFreeTimeStart, strFreeTimeMinutes);
					intMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + intRemainingFreeTimeMinutes;
					objDictionary.put("strRemainingFreeTimeMinutes", Integer.toString(intRemainingFreeTimeMinutes));
					strEndTime = clsCommonMobile.AddTimeToExistingTime(strStartTime, String.valueOf(intMeterRemainingTimeMinutes),"MMM dd, hh:mm a");
				}
				else
				{
					String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
					intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null, strMinutesBeforeFreeStart);
					if(intMeterRemainingTimeMinutes > Integer.parseInt(strMeterIncrementTime)+Integer.parseInt(strFreeTimeFirstPayment))
					{
						intMeterRemainingTimeMinutes = Integer.parseInt(strMeterIncrementTime)+Integer.parseInt(strFreeTimeFirstPayment);
					}
					strEndTime = clsCommonMobile.AddTimeToExistingTime(strStartTime, String.valueOf(intMeterRemainingTimeMinutes),"MMM dd, hh:mm a");
				}
		  	}
		}
		else
		{
			intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingTrueUpTime(objDictionary, null,  strTrueUpStartTime, strMeterIncrementTime) + intCurrentMeterTime + Integer.parseInt(strFreeTimeFirstPayment);
		}
		//Validate Expected Meter Time
		clsMeter.METER_ValidateExpectedMeterTime(objDictionary, null, intMeterRemainingTimeMinutes, "1");
		//Validate Parking Session
		String strTotalPayment = objDictionary.get("strTotalFee");//SENTRYMOBILE_ValidateFirstPaymentDialogAndReturnParkingFee
        objDictionary.put("strFirstPaymentFee", strTotalPayment);
		clsCommonMobile.SENTRYMOBILE_ValidateParkingSession(objDictionary,iosDriver,strStartTime, strEndTime, strTotalPayment);
        //Store Parking Id
  		clsHttpConnections.HTTPCONNECTIONS_StoreParkingId(objDictionary, "Local", "1");
  		objDictionary.remove("strMeterRemainingTimeMinutes");objDictionary.put("strMeterRemainingTimeMinutes",Integer.toString(intMeterRemainingTimeMinutes));
  	}
