	public void SENTRYMOBILE_NavigateToPageUsingMenuButtons(Map<String, String> objDictionary, IOSDriver iosDriver, String strPageName)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
		//String strCurrentPage = "";
		String strButtonName = ""; String strPageHeader = "";
		try
		{
			switch (strPageName)
			{
				case "Park":
					strButtonName = "Park";
					strPageHeader = "Enter your Parking Zone Number";
					try {
					    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(10));
					    wait.until(ExpectedConditions.elementToBeClickable(By.xpath("//XCUIElementTypeButton[contains(@name, 'Park')]"))).click();
					} catch (Exception e) {}
					Reporter.log("Navigated to the ("+strPageHeader+") page correctly");
					break;
				case "Nearby Parking":
					strButtonName = "Spots";
					strPageHeader = "Nearby Parking";
					iosDriver.findElement(By.name("Spots")).click();
					break;
				case "Pay Meter":
				case "Meter Payment":
					strButtonName = "Pay Meter";
					strPageHeader = "Meter Payment";
					iosDriver.findElement(By.name("Pay Meter")).click();
					break;
				case "Lot Payment":
					strButtonName = "Pay Lots";
					strPageHeader = "Pay Lots";
					iosDriver.findElement(By.name("Pay Lot")).click();
					break;
				case "Active":
				case "Parking Sessions":
					strButtonName = "Active";
					strPageHeader = "Parking Sessions";
					iosDriver.findElement(By.name("Active")).click();
					break;
				case "Account":
				case "Account Details":
					strButtonName = "Account";
					strPageHeader = "Account Details";
					GlobalWait(objDictionary, iosDriver, "Nearby Parking", "{ButtonExists} Nearby Parking~Account", 15);
					iosDriver.findElement(By.name("Account")).click();
					break;
				default:
					UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The page ("+strPageName+") hasn't been added-"+strMethodName);
			}
		}
		catch (Exception e){UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The page button ("+strButtonName+") did not exist or the page attributes changed-"+strMethodName);}
		try {Thread.sleep(2000);}catch (Exception e) {}//wait page to Load
		try
		{
			iosDriver.findElement(By.xpath("//XCUIElementTypeStaticText[normalize-space(@label) = '"+strPageHeader+"']"));	
			Reporter.log("Navigated to the ("+strPageHeader+") page correctly");
		}
		catch (Exception f)
		{UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The page title did not exist or the page attributes changed-"+strMethodName);}
	}
