	public void SENTRYMOBILE_CheckUserAccountBalanceAddFundsIfNeeded(Map<String, String> objDictionary, String strRole)throws IOException
	{
		HttpConnections clsHttpConnections = new HttpConnections();
		//Function Variables
		String strCurrentAccountBalance = "";
		try{strCurrentAccountBalance = clsHttpConnections.CURL_ReturnCurrentParkingAccountBalance(objDictionary,strRole);}
		catch (Exception e)
		{}
		//Add Money If Balance is less than $5.00
		double dblStringUserAccountBalance = Double.parseDouble(strCurrentAccountBalance) * .01;
		Reporter.log("The user account balance was ("+dblStringUserAccountBalance+")");
		objDictionary.put("strCurrentParkingAccountBalance", String.valueOf(dblStringUserAccountBalance));
		if(dblStringUserAccountBalance < 10.00)
		{
			//Add Money Through API
			clsHttpConnections.POST_JsonDepositFunds(objDictionary,strRole);
		}
	}
