	public void ClickPermissionAlertButton(Map<String, String> objDictionary, IOSDriver iosDriver, String strButtonName) 
	{
	    if (strButtonName == null || strButtonName.trim().isEmpty()) {UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Button name cannot be empty");}
	    // Build dynamic Class Chain locator for the requested button
	    String iosLocator = "**/XCUIElementTypeButton[`name == \"" + strButtonName + "\" OR label == \"" + strButtonName + "\"`]";
	    try {
	        // Set the custom accept button selector for this specific button
	        iosDriver.setSetting("acceptAlertButtonSelector", iosLocator);
	        // Primary method: Use Appium's alert handling with custom selector
	        iosDriver.switchTo().alert().accept();
	        Reporter.log("Permission alert button '" + strButtonName + "' clicked successfully using selector");
	    } catch (Exception e) {
	        System.out.println("⚠️ Primary method failed for button '" + strButtonName + "'. Trying fallbacks...");
	        // Fallback 1: Direct click using XPath (most reliable when alert() fails)
	        try {
	            WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(8));
	            WebElement button = wait.until(ExpectedConditions.elementToBeClickable(By.xpath("//XCUIElementTypeButton[@name='" + strButtonName + "' or @label='" + strButtonName + "']")));
	            button.click();
	            System.out.println("✅ Permission alert button '" + strButtonName + "' clicked via direct XPath");
	            return;
	        } catch (Exception ex1) {
	            // Fallback 2: Broader contains search (in case of slight text differences)
	            try {
	                WebElement button = iosDriver.findElement(By.xpath("//XCUIElementTypeButton[contains(@name, '" + strButtonName + "') or contains(@label, '" + strButtonName + "')]"));
	                button.click();
	                System.out.println("✅ Permission alert button clicked using contains()");
	                return;
	            } catch (Exception ex2) {System.out.println("❌ All fallbacks failed for button: " + strButtonName);}
	        }
	    }
	    try {Thread.sleep(1200);} catch (InterruptedException ie) {Thread.currentThread().interrupt();}
	}
