    public void ClickLink(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strLinkName, int intLinkIndex)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		WebElement objLink = GetLinkObj(objDictionary, iosdriver, strPageName, strLinkName);
		if (objLink != null)
	    {
			objLink.click();
			try {Thread.sleep(2000);}catch (Exception e) {}
			strLinkName = ConvertValues(objDictionary, iosdriver, strLinkName);
			Reporter.log("The Link (" + strLinkName + ") with index (" + intLinkIndex + ") was clicked successfully"+"");
		}
	    else
	    {
	    	if(strLinkName.equals("Next ›"))
	    	{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Link (" + strLinkName + ") did not exist-No more results existed-"+strMethodName);}
	    	else
	    	{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Link (" + strLinkName + ") did not exist-"+strMethodName);}
	    }
	}
	public void ClickTextField(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strTextfieldName, int intTextfieldIndex)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		WebElement objTextfield = GetTextFieldObj(objDictionary, iosdriver, strPageName, strTextfieldName);
		if (objTextfield != null)
	    {
			objTextfield.click();
			if(!strWaitObjects.equals(""))
			{DynamicObjectWait(objDictionary,iosdriver, strPageName);}
			else{try {Thread.sleep(2000);}catch (Exception e) {}}
			strTextfieldName = ConvertValues(objDictionary, iosdriver, strTextfieldName);
			Reporter.log("The Textfield (" + strTextfieldName + ") with index (" + intTextfieldIndex + ") was clicked successfully"+"");
		}
	    else
	    {
	    	if(strTextfieldName.equals("Next ›"))
	    	{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Textfield (" + strTextfieldName + ") did not exist-No more results existed-"+strMethodName);}
	    	else
	    	{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Textfield (" + strTextfieldName + ") did not exist-"+strMethodName);}	    }
	}
	public void NavigateToLinkInScrollableList(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strLinkName, String strScrollableListboxName, WebElement element)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		String strCondition = "False";String strLastItemBeforeScroll = "";String strLastItemAfterScroll = "";
		do
	    {
			List<WebElement> lsItemsBeforeScroll = iosdriver.findElements(By.xpath("//UIAApplication[1]/UIAWindow[1]/UIATableView[1]/UIATableCell[13]/UIAStaticText[1]"));
			strLastItemBeforeScroll = lsItemsBeforeScroll.get(lsItemsBeforeScroll.size() - 1).getText();
			SwipeUpToDownOnElement(iosdriver,element);
			strCondition = ConditionalStepLink(objDictionary,iosdriver, strPageName, strLinkName, 1, "Exists",  "");
			List<WebElement> lsItemsAfterScroll = iosdriver.findElements(By.id("//UIAApplication[1]/UIAWindow[1]/UIATableView[1]/UIATableCell[13]/UIAStaticText[1]"));
			strLastItemAfterScroll = lsItemsAfterScroll.get(lsItemsAfterScroll.size() - 1).getText();
			if(strLastItemBeforeScroll.equals(strLastItemAfterScroll))
			{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Link (" + strLinkName + ") did not exist in the ScrollableListbox ("+strScrollableListboxName+")-"+strMethodName);}
	    }while (strCondition == "False");
	}
