	public void PopulateAction(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strAction, String strObjectNames,String strObjectValues)
	{
		//Check If Current Page is expected page
		//String strPageURL = GetPageURL(objDictionary, strPageName);
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		String[] arrObjectNames = strObjectNames.split("\\|", -1);
		String[] arrObjectValues = strObjectValues.split("\\|", -1);
		int intCounter = 0;
		String strObjectnameWithValues = "";
		for (String strObjectName : arrObjectNames)
        {
			 String[] arrObjectName = strObjectName.split("}");
			 String strObjectType = arrObjectName[0].substring(1);
			 strObjectName = arrObjectName[1].substring(1);
             if(!arrObjectValues[intCounter].equals(""))
             {
	             switch (strObjectType)
	             {
	             	case "CB":
	             		PopulateCheckbox(objDictionary, iosdriver, strPageName, strObjectName, arrObjectValues[intCounter]);
	             		break;
	             	case "L":
	             	case "UDL":
	             		PopulateListbox(objDictionary, iosdriver, strPageName, strObjectName, arrObjectValues[intCounter]);
	                    break;
	             	case "T":
	             		PopulateTextfield(objDictionary, iosdriver, strPageName, strObjectName, arrObjectValues[intCounter]);
	                    break;
	             	case "RB":
	             		PopulateRadioButton(objDictionary, iosdriver, strPageName, strObjectName, arrObjectValues[intCounter]);
	                    break;
	             	default:
	             		UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Object Type(" + strObjectType + ") does not exist or has not been coded-"+strMethodName);
	             }
             }
             strObjectnameWithValues = strObjectnameWithValues+"|"+strObjectName+","+arrObjectValues[intCounter];
             intCounter++;
        }
		String strStoredPopulateVariable = objDictionary.get("strStoredPopulateVariable");
		if (strStoredPopulateVariable != null)
        {
			Reporter.log("The (" + strAction.replaceAll("Populate ", "") + ") field(s) were populated correctly (" + strStoredPopulateVariable + ") - Values("+strObjectnameWithValues+")");
		 	objDictionary.remove("strStoredPopulateVariable");
        }
        else
        { Reporter.log("The (" + strAction.replaceAll("Populate ", "") + ") field(s) were populated correctly - Values("+strObjectnameWithValues+")");}
 	}
	public void PopulateCheckbox(Map<String, String> objDictionary,IOSDriver iosdriver, String strPageName, String strObjectName, String strObjectValue)
	{
		StringBuilder clsStringBuilder = new StringBuilder();
		String strCheckboxGroup = "";
		String strCheckBoxIndex = "";
		if(strObjectName.contains("~"))
		{
			 String[] arrObjectName = strObjectName.split("~");
			 strCheckboxGroup = arrObjectName[0];
			 strObjectName = arrObjectName[1];
			 strCheckBoxIndex = arrObjectName[2];
		}
		WebElement objCheckbox = GetCheckboxObj(objDictionary, iosdriver,strPageName,"",strObjectName);
		if (objCheckbox != null)
	    {
	    	if(strSpecialInstruction.equals("ButtonCheckBox")){objCheckbox.click();strSpecialInstruction = "";}
	    	else
	    	{
		    	if (strObjectValue.equals("Checked"))
	            {
		    		//System.out.println(objCheckbox.isSelected());
		    		if (!objCheckbox.isSelected()){objCheckbox.click();}
	            }
		    	else
		    	{
		    		//System.out.println(objCheckbox.isSelected());
		    		if (objCheckbox.isSelected()){objCheckbox.click();}
	             }
	    	}
	    	if(!strWaitObjects.equals("")){DynamicObjectWait(objDictionary,iosdriver, strPageName);}
	    }
	    else
	    {Assert.fail(clsStringBuilder.toString()+"The Checkbox (" + strObjectName + ") did not exist");}
	}
