	public void PopulateListbox(Map<String, String> objDictionary,IOSDriver iosdriver, String strPageName, String strObjectName, String strObjectValue)
	{
		StringBuilder clsStringBuilder = new StringBuilder();
		WebElement objListbox = GetListboxObj(objDictionary,iosdriver,strPageName,strObjectName);
		String strListboxItemExisted = "False";
	    if (objListbox != null)
	    {
	    	if(strListboxPopulationType.equals("Text"))//Value
	    	{
	        	//Populate Listbox By Text
	    		List<WebElement> options = null;
	            try {options = objListbox.findElements(By.tagName("option"));}
	            catch(Exception e) {System.out.print("PopulateListbox"+e);}
	            for (WebElement option : options)
	            {
	            	System.out.print('\r' + option.getText().trim());System.out.print('\r'+strObjectValue);
	            	if (strObjectValue.equals(option.getText().trim())) {option.click();strListboxItemExisted = "True";break;}
	            }
	            if(strListboxItemExisted.equals("False")){Assert.fail(clsStringBuilder.toString()+"The Value (" + strObjectValue + ") did not exist in the Listbox (" + strObjectName + ")");}
	        }
	    	else
	        {
	    		//Populate Listbox By Value
	    		List<WebElement> options = objListbox.findElements(By.tagName("option"));
	            String strDefaultListboxItem = "";
	            for (WebElement option : options) {strDefaultListboxItem = option.getText();break;}
	            if (strObjectValue != strDefaultListboxItem)
	            {
	            	Select dropdown = new Select(objListbox);
	            	try{dropdown.selectByValue(strObjectValue);}
	            	catch(Exception e){Assert.fail(clsStringBuilder.toString()+"The Value (" + strObjectValue + ") did not exist in the Listbox (" + strObjectName + ")");}
			    }
			 }
	    }
	    else
	    {Assert.fail(clsStringBuilder.toString()+"The Listbox (" + strObjectName + ") did not exist");}
	    if (strStoreValueAsVariableName != "")
        {
            objDictionary.remove(strStoreValueAsVariableName); objDictionary.put(strStoreValueAsVariableName, strObjectValue);
            String strStoredPopulateVariable = objDictionary.get("strStoredPopulateVariable");
            if (strStoredPopulateVariable != null)
            {objDictionary.remove("strStoredPopulateVariable");objDictionary.put("strStoredPopulateVariable", strStoredPopulateVariable + strStoreValueAsVariableName + ": " + strObjectValue + "|");}
            else
            { objDictionary.put("strStoredPopulateVariable", strStoreValueAsVariableName + ": " + strObjectValue + "|"); }
            strStoreValueAsVariableName = "";
        }
	}
	public void PopulateScrollableListbox(Map<String, String> objDictionary,IOSDriver iosDriver, String strPageName, String strScrollableListboxName, String strListboxValue)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		switch (strPageName)
		{
			case "Review and Pay":
				switch (strScrollableListboxName)
				{
					case "Select Payment Option":
					    //Click Payment Options
						try {
						    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(5));
						    WebElement element = wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//XCUIElementTypeButton[@name='Select Payment Option']")));
						    element.click();}
						catch (Exception e) {clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Listbox (" + strScrollableListboxName + ") did not exist - " + strMethodName);}
						// Select specific Payment Option
						try {
						    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(10));
						    WebElement targetElement = wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//XCUIElementTypeButton[@name='" + strListboxValue + "']")));
						    targetElement.click();
						    Reporter.log("The ListboxValue (" + strListboxValue + ") was clicked successfully.");
						} 
						catch (Exception e) {clsCommonMobile.UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The ListboxValue (" + strListboxValue + ") did not exist - " + strMethodName);}
						break;
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Page ("+strPageName+") does not have any existing ScrolableListboxName identified-"+strMethodName);
				}
			}
		if (strStoreValueAsVariableName != "")
        {
            objDictionary.remove(strStoreValueAsVariableName); objDictionary.put(strStoreValueAsVariableName, strListboxValue);
            String strStoredPopulateVariable = objDictionary.get("strStoredPopulateVariable");
            if (strStoredPopulateVariable != null)
            {
            	objDictionary.remove("strStoredPopulateVariable");
            	objDictionary.put("strStoredPopulateVariable", strStoredPopulateVariable + strStoreValueAsVariableName + ": " + strListboxValue + "|");
            }
            else
            { objDictionary.put("strStoredPopulateVariable", strStoreValueAsVariableName + ": " + strListboxValue + "|"); }
            strStoreValueAsVariableName = "";
        }
	}
	public void PopulateTextfield(Map<String, String> objDictionary,IOSDriver iosdriver, String strPageName, String strObjectName, String strObjectValue)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		WebElement objTextField = GetTextFieldObj(objDictionary, iosdriver, strPageName, strObjectName);
		strObjectValue = ConvertValues(objDictionary, iosdriver, strObjectValue);
		if (objTextField != null)
	    {
			try
			{
				if(strSpecialInstruction.equals("ClearField")){objTextField.clear();strSpecialInstruction = "";}
				objTextField.sendKeys(strObjectValue);
				//This removes the Security Password Keyboard
				if(strPageName.equals("Login") && strObjectName.equals("Password")||strPageName.equals("Sign Up") && strObjectName.equals("Password")||strPageName.equals("Sign Up") && strObjectName.equals("Confirm password"))
				{
					Thread.sleep(500);
			        try {iosdriver.executeScript("mobile: tap", Map.of("x", 195, "y", 120));} catch (Exception ignored) {}
				}
			}
			catch(Exception a)
			{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"Unable to Populate TextField-"+strMethodName);}
		}
	    else
	    {UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The TextField (" + strObjectName + ") did not exist-"+strMethodName);}
		try {Thread.sleep(500);}catch (Exception e) {}
		if (strStoreValueAsVariableName != "")
        {
            objDictionary.remove(strStoreValueAsVariableName); objDictionary.put(strStoreValueAsVariableName, strObjectValue);
            String strStoredPopulateVariable = objDictionary.get("strStoredPopulateVariable");
            if (strStoredPopulateVariable != null)
            {objDictionary.remove("strStoredPopulateVariable");objDictionary.put("strStoredPopulateVariable", strStoredPopulateVariable + strStoreValueAsVariableName + ": " + strObjectValue + "|");}
            else
            { objDictionary.put("strStoredPopulateVariable", strStoreValueAsVariableName + ": " + strObjectValue + "|"); }
            strStoreValueAsVariableName = "";
        }
	}
