	public WebElement GetButtonObj(Map<String, String> objDictionary, IOSDriver iosDriver, String strPageName, String strButtonName)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		String strIOSUdid = objDictionary.get("strIOSUdid"); if(strIOSUdid == null){strIOSUdid = "";}
		WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(15));
        switch (strPageName)
		{
			case "Choose Parking Duration":
				switch (strButtonName)
				{
					case "Proceed":
						try {return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Proceed']")));}
						catch (Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Button (" + strButtonName + ") had not been added to GetButtonObj for the page (" + strPageName + ")-"+strMethodName);
				}
				break;
        	case "Enter your Parking Zone Number":
	       		switch (strButtonName)
					{
						case "Meter Spot Number":
							String strMeterSpotName = objDictionary.get("strMeterSpotName");
							try {
							    WebElement element = wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//XCUIElementTypeImage[@name='"+strMeterSpotName+"']")));
							    return element;
							} catch (Exception e) {return null;}
						case "Pay":
							try {
							    WebElement element = wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//XCUIElementTypeImage[@name='Pay']")));
							    return element;
							} catch (Exception e) {return null;}
						default:
							UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Button (" + strButtonName + ") had not been added to GetButtonObj for the page (" + strPageName + ")-"+strMethodName);
					}
					break;
			case "Log in":
				switch (strButtonName)
				{
					case "Log in":
						try { return iosDriver.findElement(By.xpath("(//XCUIElementTypeStaticText[@name=\"Log in\"])[2]"));}
						catch(Exception e) {return null;}
					case "Sign up":
	            		try { return iosDriver.findElement(By.xpath("//XCUIElementTypeLink[@name=\"Sign up\"]"));}
	            		catch(Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Button (" + strButtonName + ") had not been added to GetButtonObj for the page (" + strPageName + ")-"+strMethodName);
				}
				break;
			case "Parking Sessions":
				switch (strButtonName)
				{
					case "Active":
						try {
						    WebElement element = wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//XCUIElementTypeStaticText[contains(@name, 'Active')]")));
						    return element;
						} 
						catch (Exception e) {return null;}
					case "Extend":
						try 
						{
						    WebElement element = wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//XCUIElementTypeImage[@name='Extend']")));
						    return element;
						} 
						catch (Exception e) {return null;}
					case "History":
						try 
						{
						    WebElement element = wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//XCUIElementTypeStaticText[contains(@name, 'History')]")));
						    return element;
						} 
						catch (Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Button (" + strButtonName + ") had not been added to GetButtonObj for the page (" + strPageName + ")");
				}
				break;
			case "Review and Pay":
				switch (strButtonName)
				{
					case "Proceed":
					    try {
					        WebElement element = wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//XCUIElementTypeStaticText[contains(@name, 'Proceed – $')]")));
					        return element;
					    } 
					    catch (Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Button (" + strButtonName + ") had not been added to GetButtonObj for the page (" + strPageName + ")-"+strMethodName);
				}
				break;
			case "Select Your Vehicle":
				switch (strButtonName)
				{
					case "License Plate":
						String strLicensePlateNumber = objDictionary.get("strLicensePlateNumber");
						if (strLicensePlateNumber == null || strLicensePlateNumber.trim().isEmpty()) {UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"Failed to retrieve the License Plate object because the required key 'strLicensePlateNumber' was null or missing in objDictionary.");}
						try {return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeButton[@name='" + strLicensePlateNumber.toUpperCase() + "']")));}
						catch (Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Button (" + strButtonName + ") had not been added to GetButtonObj for the page (" + strPageName + ")-"+strMethodName);
				}
				break;
			case "Sign Up":
				switch (strButtonName)
				{
					case "Next":
					    try {return wait.until(ExpectedConditions.elementToBeClickable(By.xpath("//XCUIElementTypeStaticText[@name='Next']")));}
					    catch(Exception e) {return null;}
					case "Sign up":
					    try {return wait.until(ExpectedConditions.elementToBeClickable(By.xpath("(//XCUIElementTypeStaticText[@name=\"Sign up\"])[2]")));}
					    catch(Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Button (" + strButtonName + ") had not been added to GetButtonObj for the page (" + strPageName + ")-"+strMethodName);
				}
				break;
			case "User Agreement":
				switch (strButtonName)
				{
					case "Accept":
					    try {
					        return wait.until(ExpectedConditions.elementToBeClickable(By.xpath("//XCUIElementTypeStaticText[@name='Accept']")));
					    } 
					    catch (Exception e) {}
//					case "Accept-Concierge":
//						try { return iosdriver.findElement(By.name("Accept"));}catch(Exception e) {return null;}
//					case "Allow":
//						try { return iosdriver.findElement(By.name("Allow"));}catch(Exception e) {return null;}
//					case "Cancel":
//						try { return iosdriver.findElement(By.name("Cancel"));}catch(Exception e) {return null;}
					case "OK":
						try { return iosDriver.findElement(By.name("OK"));}catch(Exception e) {return null;}
					case "Remind me later":
						try { return iosDriver.findElement(By.name("Remind me later"));}catch(Exception e) {return null;}
//					case "Trust":
//						try { return iosdriver.findElement(By.xpath("//XCUIElementTypeApplication/XCUIElementTypeWindow[7]/XCUIElementTypeOther[3]/XCUIElementTypeAlert/XCUIElementTypeOther/XCUIElementTypeOther/XCUIElementTypeOther[2]/XCUIElementTypeOther[3]/XCUIElementTypeOther/XCUIElementTypeOther/XCUIElementTypeOther"));}catch(Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Button (" + strButtonName + ") had not been added to GetButtonObj for the page (" + strPageName + ")-"+strMethodName);
				}
				break;
			default:
				UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Page ("+strPageName+") does not have any existing Buttons identified-"+strMethodName);
		}
		return null;
	}
