	public WebElement GetLinkObj(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strLinkName)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		strLinkName = ConvertValues(objDictionary, iosdriver, strLinkName);
		String strOSVersion = System.getProperty("os.version");
		if(strLinkName == ""){UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The strLinkName value was blank-"+strMethodName);}
		switch (strPageName)
		{
			case "Log in":
				switch (strLinkName)
				{
					case "Log in":
						try { return iosdriver.findElement(By.name("Log in"));}
						catch(Exception e) {return null;}
					case "Sign up":
						try { return iosdriver.findElement(By.name("Sign up"));}
						catch(Exception e) {return null;}
					case "Ok":
						try { return iosdriver.findElement(By.name("Ok"));}
						catch(Exception e) {return null;}
					default:
						try {iosdriver.findElement(By.xpath("//*[@text='"+strLinkName+"']"));}
						catch(Exception e) {return null;}
				}
			default:
				try {return iosdriver.findElement(By.xpath("//*[@text='"+strLinkName+"']"));}catch(Exception e) {return null;}
		}
	}
