	public WebElement GetTextFieldObj(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strTextFieldName)
	{
		Meter clsMeter = new Meter();
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		try {Thread.sleep(1000);}catch (Exception e) {}
		WebDriverWait wait = new WebDriverWait(iosdriver, Duration.ofSeconds(5));
		switch (strPageName)
		{
			case "iOS Settings":
				switch (strTextFieldName)
				{
					case "Search":
						try { return iosdriver.findElement(By.xpath("//XCUIElementTypeSearchField[@name=\"Search\"]"));}
						catch(Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Textfield (" + strTextFieldName + ") had not been added for the page (" + strPageName + ")-"+strMethodName);
				}
			case "Enter your Parking Zone Number":
				switch (strTextFieldName)
				{
					case "Zone Number":
						strSpecialInstruction = "ClearField";
						try {return new WebDriverWait(iosdriver, Duration.ofSeconds(10)).until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeTextField")));}
						catch (Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Textfield (" + strTextFieldName + ") had not been added for the page (" + strPageName + ")-"+strMethodName);
				}
			case "Log in":
				switch (strTextFieldName)
				{
					case "Email or Phone number":
						strSpecialInstruction = "ClearField";
						try {return new WebDriverWait(iosdriver, Duration.ofSeconds(10)).until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Email or Phone number']/following-sibling::XCUIElementTypeTextField[1]")));}
						catch (Exception e) {return null;}
					case "Password":
						strSpecialInstruction = "ClearField";
						try {
						    WebElement passwordField = new WebDriverWait(iosdriver, Duration.ofSeconds(10)).until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Password']/following-sibling::*[self::XCUIElementTypeTextField or self::XCUIElementTypeSecureTextField]")));
						    passwordField.click();  //Activate the Password Secure Field
						} catch (Exception e) {return null;}
						try { return iosdriver.findElement(By.xpath(".//XCUIElementTypeSecureTextField[1]"));}catch(Exception e) {return null;}
					case "Select a municipality to continue":
						try { return iosdriver.findElement(By.xpath("//XCUIElementTypeApplication[1]/XCUIElementTypeWindow[1]/XCUIElementTypeOther[1]/XCUIElementTypeOther[1]/XCUIElementTypeOther[1]/XCUIElementTypeOther[1]/XCUIElementTypeOther[3]/XCUIElementTypeTextField[1]"));}catch(Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Textfield (" + strTextFieldName + ") had not been added for the page (" + strPageName + ")-"+strMethodName);
				}
			case "Sign Up":
				switch (strTextFieldName)
				{
					case "Confirm password":
						try {
						    WebElement passwordField = new WebDriverWait(iosdriver, Duration.ofSeconds(10)).until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Confirm password']/following-sibling::XCUIElementTypeTextField")));
						    passwordField.click();  //Activate the Password Secure Field
						} catch (Exception e) {return null;}
						try { return iosdriver.findElement(By.xpath(".//XCUIElementTypeSecureTextField[1]"));}catch(Exception e) {return null;}
					case "Email":
						try {return wait.until(ExpectedConditions.elementToBeClickable(By.xpath("//XCUIElementTypeStaticText[@name='Email']/following-sibling::XCUIElementTypeTextField")));}
					    catch(Exception e) {return null;}
					case "First Name":
						try {return wait.until(ExpectedConditions.elementToBeClickable(By.xpath("//XCUIElementTypeStaticText[@name='First Name']/following-sibling::XCUIElementTypeTextField")));}
					    catch(Exception e) {return null;}
					case "Last Name":
						try {return wait.until(ExpectedConditions.elementToBeClickable(By.xpath("//XCUIElementTypeStaticText[@name='Last Name']/following-sibling::XCUIElementTypeTextField[2]")));}
					    catch(Exception e) {return null;}
					case "Password":
						try {
						    WebElement passwordField = new WebDriverWait(iosdriver, Duration.ofSeconds(10)).until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Password']/following-sibling::XCUIElementTypeTextField")));
						    passwordField.click();  //Activate the Password Secure Field
						} catch (Exception e) {return null;}
						try { return iosdriver.findElement(By.xpath(".//XCUIElementTypeSecureTextField[1]"));}catch(Exception e) {return null;}
					case "Phone number":
					    try {return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Phone number']/following::XCUIElementTypeTextField[1]")));}
					    catch (Exception e) {return null;}
					default:
						UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Textfield (" + strTextFieldName + ") had not been added for the page (" + strPageName + ")-"+strMethodName);
				}
			default:
				UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Page ("+strPageName+") does not have any existing Textfield-"+strMethodName);
		}
		return null;
	}
	public WebElement GetTextObj(Map<String, String> objDictionary,IOSDriver iosDriver, String strPageName, int intTextIndex, String strTextName)
	{
		Meter clsMeter = new Meter();
		switch (strPageName)
		{
			case "Choose Parking Duration":
				switch (strTextName)
				{
					case "Choose Parking Duration":
						try {
						    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(30));
						    return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Choose Parking Duration']")));
						} catch (Exception e) {return null;}
					case "Max Parking Time":
					    try {
					        WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(10));
					        return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[contains(@name, 'Max Parking Time')]")));
					    } catch (Exception e) {return null;}
					case "Spot":
						try {
						    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(10));
						    WebElement sessionCard = wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Spot']/following-sibling::XCUIElementTypeStaticText")));
						    return sessionCard;
						} catch (Exception e) {return null;}
					case "Vehicle":
					    try 
					    {
					        WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(10));
					        return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Vehicle']/following-sibling::XCUIElementTypeStaticText")));
					    } 
					    catch (Exception e) {return null;}
					default:
						try {return iosDriver.findElement(By.xpath("//*[@text='"+strTextName+"']"));}catch(Exception e) {return null;}
				}
			case "Enter your Parking Zone Number":
				switch (strTextName)
				{
					case "Spot Details":
						try {
						    String strMeterSpotName = objDictionary.get("strMeterSpotName");
						    if (strMeterSpotName == null || strMeterSpotName.trim().isEmpty()) {
						        return null;
						    }
						    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(15));
						    return wait.until(ExpectedConditions.visibilityOfElementLocated(
						        By.xpath("//XCUIElementTypeImage[contains(@name, '" + strMeterSpotName + "') and contains(@name, 'Time Limit')]")
						    ));
						} catch (Exception e) {
						    return null;
						}
					default:
						try {return iosDriver.findElement(By.xpath("//*[@text='"+strTextName+"']"));}catch(Exception e) {return null;}
				}
		
			case "Log in":
				switch (strTextName)
				{
					case "Invalid credentials, please contact customer support.":
						try {
						    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(10));
						    return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Invalid credentials, please contact customer support.']")));
						} catch (Exception e) {return null;}
					default:
						try {return iosDriver.findElement(By.xpath("//*[@text='"+strTextName+"']"));}catch(Exception e) {return null;}
				}
			case "Parking Sessions":
				switch (strTextName)
				{
					case "Parking Session Details":
						String strMeterSpotName = objDictionary.get("strMeterSpotName");
						try {
						    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(90));
						    return wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//XCUIElementTypeOther[contains(@name, 'Spot : " + strMeterSpotName + "')]")));}
							catch (Exception e) {return null;}
					default:
						try {return iosDriver.findElement(By.xpath("//*[@text='"+strTextName+"']"));}catch(Exception e) {return null;}
				}
			case "Review and Pay":
				switch (strTextName)
				{
					case "Convenience Fee":
					    try {
					        WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(10));
					        return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Convenience Fee']/following-sibling::XCUIElementTypeStaticText")));}
					    	catch (Exception e) {return null;}
					case "Parking Fee":
						try {
						    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(10));
						    return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Parking Fee']/following-sibling::XCUIElementTypeStaticText")));}
							catch (Exception e) {return null;}
					case "Spot":
						try {
						    WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(5));
						    return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Spot']/following-sibling::XCUIElementTypeStaticText")));}
							catch (Exception e) {return null;}
					case "Total Fee":
					    try {
					        WebDriverWait wait = new WebDriverWait(iosDriver, Duration.ofSeconds(10));
					        return wait.until(ExpectedConditions.visibilityOfElementLocated(By.xpath("//XCUIElementTypeStaticText[@name='Total Fee']/following-sibling::XCUIElementTypeStaticText")));}
					    	catch (Exception e) {return null;}
					default:
						try {return iosDriver.findElement(By.xpath("//*[@text='"+strTextName+"']"));}catch(Exception e) {return null;}
				}
			case "Sign Up":
				switch (strTextName)
				{
					case "Enter valid email address":
						try {return iosDriver.findElement(By.xpath("//XCUIElementTypeStaticText[@name='Enter valid email address']"));}
						catch (Exception e) {return null;}
					case "Passwords do not match":
						try {return iosDriver.findElement(By.xpath("//XCUIElementTypeStaticText[@name=\"Passwords do not match\"]"));}
						catch (Exception e) {return null;}
					case "Password must be at least 12 characters, at least 1 upper case letter, at least 1 lower case letter, at least 1 number, at least 1 special character":
						try {return iosDriver.findElement(By.xpath("//XCUIElementTypeStaticText[@name=\"Password must be at least 12 characters, at least 1 upper case letter, at least 1 lower case letter, at least 1 number, at least 1 special character\"]"));}
						catch (Exception e) {return null;}
					case "Please enter last name":
						try {return iosDriver.findElement(By.xpath("//XCUIElementTypeStaticText[@name=\"Please enter last name\"]"));}
						catch (Exception e) {return null;}
					default:
						try {return iosDriver.findElement(By.xpath("//XCUIElementTypeStaticText[@name='" + strTextName + "']"));}
						catch (Exception e) {return null;}
				}
			default:
				try {return iosDriver.findElement(By.xpath("//*[@text='"+strTextName+"']"));}catch(Exception e) {return null;}
		}
	}
