	public IOSDriver DynamicObjectWait(Map<String, String> objDictionary,IOSDriver iosdriver, String strPageName)
    {
		Meter clsMeter = new Meter();
		String strObjectValue2 = "";
		String strTimeoutFlag = "False";
		Timestamp currentTime = new Timestamp(System.currentTimeMillis());
        Calendar cal = Calendar.getInstance();
        cal.setTimeInMillis(currentTime.getTime());
        cal.add(Calendar.SECOND, intWaitTime);
        Timestamp endTime = new Timestamp(cal.getTime().getTime());
        do
        {
            String[] arrWaitObjects = strWaitObjects.split("\\|");
            for (String WaitObject : arrWaitObjects)
            {
            	String[] arrWaitObject = WaitObject.split("}");
                String strWaitType = arrWaitObject[0].substring(1);
                String[] arrWaitValue = arrWaitObject[1].trim().split("~");
                int intWaitValueLenght = arrWaitValue.length;
                String strWaitValue = arrWaitValue[0];
                if (intWaitValueLenght == 2) {strObjectValue2 = arrWaitValue[1];}
                strActualWaitType = strWaitType;
                strActualWaitValue = strWaitValue;
                WebElement objName = null;

                try
                {
                	IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
                	String strConditional = clsCommonMobile.ConditionalStepText(objDictionary,iosdriver, "Meter Payment", "Please select the payment option", 1, "Exists", "");
        			if(strConditional.equals("False"))
        			{
        				iosdriver.findElement(By.id("Close")).click();
        				Reporter.log("<font color=‘blue’>Close link clicked on Alert Dialog</font>");
        			}
                }
                catch(Exception a) {}
                switch (strWaitType)
                {
	            		case "ButtonExists":
		                	strActualWaitValue = strObjectValue2;
		            		objName = GetButtonObj(objDictionary, iosdriver, strWaitValue, strObjectValue2);
		            		if(objName != null)
		            		{strWaitObjects = "";intWaitTime = 30;return iosdriver;}
		            		break;
	                	case "LinkExists":
	                		objName = GetLinkObj(objDictionary, iosdriver, strPageName, strWaitValue);
	                		if(objName != null){strWaitObjects = "";intWaitTime = 30;return iosdriver;}
	                		break;
	                	case "PageExists":
	                		objName = GetPageObj(objDictionary,iosdriver,strWaitValue);
	                		if(objName != null){strWaitObjects = "";intWaitTime = 30;return iosdriver;}
	                		break;
	                	case "TextExists":
	                		strActualWaitValue = strObjectValue2;
	                		objName = GetTextObj(objDictionary,iosdriver, strWaitValue, 1, strObjectValue2);
	                		if(objName != null){strWaitObjects = "";intWaitTime = 30; return iosdriver;}
	                		break;
	                	case "TextFieldExists":
	                		strActualWaitValue = strObjectValue2;
	                		objName = GetTextFieldObj(objDictionary, iosdriver, strWaitValue, strObjectValue2);
	                		if(objName != null){strWaitObjects = "";intWaitTime = 30; return iosdriver;}
	                		break;
	                	case "ThreadStoreMeterValues":
	                		String strMeterValidTimePurchased = objDictionary.get("strMeterValidTimePurchased");
	                		if(strMeterValidTimePurchased == null){clsMeter.StoreMaxTime_MaxRemaining_ValidTimePurchased_ValidTimeRemaining_Violation_Unlocked(objDictionary);}
	                		break;
	            }
                currentTime = new Timestamp(System.currentTimeMillis());
                if (currentTime.getTime() > endTime.getTime())
                {UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"None of the expected objects (" + strWaitObjects + ") existed after (" + intWaitTime + ") seconds");}
            }
        }while (strTimeoutFlag == "False");
		return iosdriver;
    }
	public IOSDriver GlobalWait(Map<String, String> objDictionary,IOSDriver iosdriver, String strPageName, String strWaitObjects, int intWaitTime)
	{
		Meter clsMeter = new Meter();
		String strObjectValue2 = "";
		String strTimeoutFlag = "False";
        Timestamp currentTime = new Timestamp(System.currentTimeMillis());
        Calendar cal = Calendar.getInstance();
        cal.setTimeInMillis(currentTime.getTime());
        cal.add(Calendar.SECOND, intWaitTime);
        Timestamp endTime = new Timestamp(cal.getTime().getTime());
        HttpConnections clsHttpConnections = new HttpConnections();
    	do
        {
            String[] arrWaitObjects = strWaitObjects.split("\\|");
            for (String WaitObject : arrWaitObjects)
            {
                String[] arrWaitObject = WaitObject.split("}");
                String strWaitType = arrWaitObject[0].substring(1);
                String[] arrWaitValue = arrWaitObject[1].trim().split("~");
                int intWaitValueLenght = arrWaitValue.length;
                String strWaitValue = arrWaitValue[0];
                if (intWaitValueLenght == 2) {strObjectValue2 = arrWaitValue[1];}
                strActualWaitType = strWaitType;
                strActualWaitValue = strWaitValue;
                WebElement objName = null;
                try {iosdriver.findElement(By.id("Close")).click();Reporter.log("<font color=‘blue’>Close link clicked on Alert Dialog</font>");}catch(Exception a) {}
                switch (strWaitType)
                {
	                case "ButtonExists":
		                	strActualWaitValue = strObjectValue2;
		                	objName = GetButtonObj(objDictionary, iosdriver, strWaitValue, strObjectValue2);
		            		if(objName != null)
		            		{
		            			//The Nearby Parking Page takes a while to Load
			                	if(strWaitValue.equals("Nearby Parking") && strObjectValue2.equals("Pay Meter"))	{try {Thread.sleep(5000);}catch (Exception e) {}}
			                	strWaitObjects = "";intWaitTime = 30;return iosdriver;
		            		}
		            		break;
	                	case "LinkExists":
	                		objName = GetLinkObj(objDictionary, iosdriver, strPageName, strWaitValue);
	                		if(objName != null)
	                		{strWaitObjects = "";intWaitTime = 30;return iosdriver;}
	                		break;
	                	case "PageExists":
	                		objName = GetPageObj(objDictionary,iosdriver,strWaitValue);
	                		if(objName != null)
	                		{strWaitObjects = "";intWaitTime = 30;return iosdriver;}
	                		break;
	                	case "TextExists":
	                		strActualWaitValue = strObjectValue2;
	                		objName = GetTextObj(objDictionary,iosdriver, strPageName, 1, strObjectValue2);
	                		if(objName != null){strWaitObjects = "";intWaitTime = 30;return iosdriver;}
	                		break;
	                	case "TextFieldExists":
	                		strActualWaitValue = strObjectValue2;
	                		objName = GetTextFieldObj(objDictionary, iosdriver, strWaitValue, strObjectValue2);
	                		if(objName != null){strWaitObjects = "";intWaitTime = 30; return iosdriver;}
	                		break;
	                	case "WaitUntilMeterVariableBegunEqualTrue":
	                		String strBegunVariable = clsMeter.GetMeterBegunValue(objDictionary, null,"1","Local");
	                		if(strBegunVariable.equals("True"))
	                		{
	                			Reporter.log("GlobalWait: The meter variable begun equalled true"+"");
	                			strWaitObjects = "";intWaitTime = 30;return iosdriver;
	                		}
	                		break;
	                	case "WaitUntilJsonParkingSessionInformationNotBlank":
	                		String IsBlank = clsHttpConnections.CheckJsonParkingSessionInformationIsBlank(objDictionary);
	                		if(IsBlank.equals("False")) {strWaitObjects = "";intWaitTime = 30; return iosdriver;}
	                		break;
                }
                currentTime = new Timestamp(System.currentTimeMillis());
                if (currentTime.getTime() > endTime.getTime())
                {UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"None of the expected objects (" + strWaitObjects + ") existed after (" + intWaitTime + ") seconds");}
            }
        }while (strTimeoutFlag == "False");
        return iosdriver;
	}
