	public String StoreText(Map<String, String> objDictionary, IOSDriver iosDriver, String strPageName, String strTextName, int intTextIndex, String strVariableName)
	{
		String strTextValue = "";
		WebElement objText = GetTextObj(objDictionary,iosDriver, strPageName, intTextIndex, strTextName);
		if (objText == null)
		{UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The stored page text (" + strTextName + ") with index (" + intTextIndex + ") did not exist)");}
		switch (strTextName)
	    {
			default:
				 if (!objText.getText().equals(""))
                 {
                     switch (strSpecialInstruction)
                     {
                         case "outerText":
                             strTextValue = objText.getAttribute("outerText");
                             break;
                         default:
                             strTextValue = objText.getText().replace("\n", "").replace("\r", "").trim();
                             break;
                     }
                 }
	    }
		objDictionary.remove(strVariableName);
		objDictionary.put(strVariableName, strTextValue);
		Reporter.log("The text name (" + strTextName + ") value (" + strTextValue + ") was stored as variable name (" + strVariableName + ")");
		return strTextValue;
	}
