	public String StoreButtonValue(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strButtonName, int intButtonIndex, String strVariableName)
	{
		String strButtonValue = "";
		WebElement objButton = GetButtonObj(objDictionary,iosdriver, strPageName, strButtonName);
		if (objButton == null){UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The button (" + strButtonName + ") with index (" + intButtonIndex + ") did not exist)");}
        strButtonValue = objButton.getAttribute("value");
		objDictionary.remove(strVariableName);
		objDictionary.put(strVariableName, strButtonValue);
		Reporter.log("The Button (" + strButtonName + ") value (" + strButtonValue + ") was stored as variable name (" + strVariableName + ")");
		return strButtonValue;
	}
