	public void VerificationPointTextField(Map<String, String> objDictionary,IOSDriver iosdriver, String strPageName, String strTextFieldName, int intTextFieldIndex, String strValidationType, String strTextFieldVaue)
    {
		WebElement objTextField = GetTextFieldObj(objDictionary, iosdriver, strPageName, strTextFieldName);
		strTextFieldVaue = ConvertValues(objDictionary, iosdriver, strTextFieldVaue);
		if (objTextField != null)
	    {
			switch (strValidationType)
            {
				case "Contains":
					if(objTextField.getText().toLowerCase().contains(strTextFieldVaue.toLowerCase()))
	            	{Reporter.log("The textfield (" + strTextFieldName + ") with index (" + intTextFieldIndex + ") contains (" + strTextFieldVaue + ")"+"");}
	            	else
	            	{UpdateErrorMessageWithPivotalData(objDictionary,iosdriver,"The textfield (" + strTextFieldName + ") with index (" + intTextFieldIndex + ") did not contain (" + strTextFieldVaue + ") - actual value (" + objTextField.getText() + ")");}
	           		return;
				case "Value":
					if(objTextField.getText().toLowerCase().equals(strTextFieldVaue.toLowerCase()))
	            	{Reporter.log("The textfield (" + strTextFieldName + ") with index (" + intTextFieldIndex + ") equaled (" + strTextFieldVaue + ")"+"");}
	            	else
	            	{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The textfield (" + strTextFieldName + ") with index (" + intTextFieldIndex + ") did not equal (" + strTextFieldVaue + ") - actual value (" + objTextField.getText() + ")");}
	           		return;
                case "Disabled":
	                if (!objTextField.isEnabled()){Reporter.log("The TextField (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") was disabled");}
	                else
	                {UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The TextField  (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") was not disabled");}
	           		return;
	            case "Does Not Exist":
	            	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The TextField  (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") existed");
	            case "Enabled":
	            	if (objTextField.isEnabled()){Reporter.log("The TextField (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") was enabled");}
	            	else
	            	{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The TextField (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") was not enabled");}
	           		return;
	            case "Exists":
	            	Reporter.log("The TextField (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") existed"+"");
	                return;
	            default:
	            	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The TextField validation type (" + strValidationType + ") hasn't been coded yet - VerificationPointTextField");
            }
		}
	    else
	    {
	    	switch (strValidationType)
            {
                case "Does Not Exist":
                	Reporter.log("The TextField  (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") did not exist");
	                return;
                case "Exists":
                	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Textfield (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") did not exist");
           		default:
                	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Textfield (" + strTextFieldName + ") at index (" + intTextFieldIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation");
            }
	    }
    }
	public void VerificationPointText(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strTextName, int intTextIndex, String strValidationType, String strTextVaue)
    {
		WebElement objText = GetTextObj(objDictionary,iosdriver, strPageName, intTextIndex, strTextName);
		strTextVaue = ConvertValues(objDictionary, iosdriver, strTextVaue);
		if (objText != null)
	    {
			switch (strValidationType)
            {
				case "Contains":
					//Reporter.log("Use this to debug" + objText.getText());
					if(objText.getText().contains(strTextVaue))
					{Reporter.log("The Text (" + strTextName + ") with index (" + intTextIndex + ") contained (" + strTextVaue + ")"+"");}
					else
					{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Text (" + strTextName + ") with index (" + intTextIndex + ") did not contain (" + strTextVaue + ") - actual value (" + objText.getText() + ")");}
					return;
				case "Disabled":
	                if (!objText.isEnabled())
	                {Reporter.log("The Text (" + strTextName + ") at index (" + intTextIndex + ") was disabled"+"");}
	                else
	                {UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Text  (" + strTextName + ") at index (" + intTextIndex + ") was not disabled");}
	                return;
	            case "Does Not Exist":
	            	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Text  (" + strTextName + ") at index (" + intTextIndex + ") existed");
	            case "Enabled":
	            	if (objText.isEnabled()){Reporter.log("The Text (" + strTextName + ") at index (" + intTextIndex + ") was enabled");}
	            	else
	            	{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") was not enabled");}
	            	return;
	            case "Exists":
	            	Reporter.log("The Text (" + strTextName + ") at index (" + intTextIndex + ") existed"+"");
	                return;
	            case "Value":
	            	System.out.print(objText.getText().trim());
            		System.out.print(strTextVaue);
            		if(objText.getText().replaceAll("(?:\\n|\\r)", " ").trim().equals(strTextVaue.replaceAll("(?:\\n|\\r)", " ").trim()))
            		{Reporter.log("The Text (" + strTextName + ") with index (" + intTextIndex + ") equaled (" + strTextVaue + ")"+"");}
            		else
            		{UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Text (" + strTextName + ") with index (" + intTextIndex + ") did not equal (" + strTextVaue + ") - actual value (" + objText.getText().replaceAll("(?:\\n|\\r)", " ").trim() + ")");}
            		return;
            	default:
            		UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Text validation type (" + strValidationType + ") hasn't been coded yet - VerificationPointText");
            }
		}
	    else
	    {
	    	switch (strValidationType)
	        {
	            case "Does Not Exist":
	            		Reporter.log("The Text  (" + strTextName + ") at index (" + intTextIndex + ") did not exist"+"");
	                return;
	            case "Exists":
	            		UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") did not exist");
		    		default:
	                	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The Text (" + strTextName + ") at index (" + intTextIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation");
            }
	    }
    }
