	public String ConditionalStepButton(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strButtonName, int intButtonIndex, String strValidationType, String strTextVaue)
    {
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		WebElement objButton = GetButtonObj(objDictionary, iosdriver, strPageName, strButtonName);
		if (objButton != null)
        {
            switch (strValidationType)
            {
                case "Disabled":
                    if (!objButton.isEnabled()) { return "True"; } else { return "False"; }
                case "Does Not Exist":
                    return "False";
                case "Enabled":
                    if (objButton.isEnabled()) { return "True"; } else { return "False"; }
                case "Exists":
                    return "True";
                case "Visible":
                    if (objButton.isDisplayed()) { return "True"; } else { return "False"; }
                case "Invisible":
                    if (objButton.isDisplayed()) { return "True"; } else { return "False"; }
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The validation type (" + strValidationType + ") hasn't been coded yet-"+strMethodName);
            }
        }
        else
        {
            switch (strValidationType)
            {
                case "Does Not Exist":
                    return "True";
                case "Exists":
                    return "False";
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The button (" + strButtonName + ") at index (" + intButtonIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation-"+strMethodName);
            }
        }
        return "";
    }
