    public void TakeIOSScreenShot(Map<String, String> objDictionary, IOSDriver iosdriver, String strShotName)
   	{
    	Meter clsMeter = new Meter();
    	clsMeter.METER_SetMeterEndTime(objDictionary);
    	File file = null;
    	String strImageURL;
    	try
    	{
	    	File screenshot = ((TakesScreenshot) iosdriver).getScreenshotAs(OutputType.FILE);
	   		File directory = new File(".");
	   		String strPath = "";
	   		if(strShotName.equals(""))	{strPath = directory.getCanonicalPath() +"/ScreenShots/Error.png";}
	   		else{strPath = directory.getCanonicalPath() +"/ScreenShots/"+strShotName+".png";}
	   		file = new File(strPath);
	   		FileUtils.copyFile(screenshot, file);
	   		strImageURL = ImgurClient.getInstance().UploadImage(file, "IOSScreenshot " + Instant.now());
	   		if (strImageURL != null)
			{
				Reporter.log("<a href=" + strImageURL + "/>IOS Screen Shot</a>");
				Reporter.log("<img src=\"" + strImageURL + "\" alt=\"\"/><br />");
			}
	   		else
	   		{
	   			Reporter.log("<a href=" + strPath + "/>IOS Screen Shot</a>");
				Reporter.log("<img src=\"" + strPath + "\" alt=\"\"/><br />");
	   		}
	    }
    	catch (Exception e)
		{
    		String strErrorMsg = "Unable To Take Screen Shot: "+e;
    		Reporter.log("<font color='red'>"+strErrorMsg+"</font>");
    	}
   	}
