	public void SwipeUpToDownOnElement(IOSDriver iosdriver,WebElement element)
	{
    	//Up To Down
		new TouchAction(iosdriver)
    	.press(PointOption.point(element.getSize().width/2,(int)(element.getSize().height * 0.2)))
    	.waitAction(WaitOptions.waitOptions(Duration.ofMillis(3000)))
    	.moveTo(PointOption.point(element.getSize().width/2,(int)(element.getSize().height * 0.8)))
    	.release().perform();
	}
	public void SwipeUp(IOSDriver iosdriver)
	{
		org.openqa.selenium.Dimension size = iosdriver.manage().window().getSize();
		// calculate coordinates for vertical swipe
		int startVerticalY = (int) (size.height * 0.8);
		int endVerticalY = (int) (size.height * 0.20);
		int startVerticalX = (int) (size.width / 2.0);
		new TouchAction<>(iosdriver)
		.press(point(startVerticalX, startVerticalY))
		.waitAction(WaitOptions.waitOptions(Duration.ofMillis(3000)))
		.moveTo(point(startVerticalX, endVerticalY))
		.release().perform();
	}
