	public void SwipeDown(IOSDriver iosdriver) {
	    // Get the screen size of the device
	    Dimension size = iosdriver.manage().window().getSize();

	    // Calculate the coordinates for vertical swipe
	    int startVerticalY = (int) (size.height * 0.8);  // Start near the bottom of the screen
	    int endVerticalY = (int) (size.height * 0.2);    // End near the top of the screen
	    int startVerticalX = (int) (size.width / 2);      // Horizontal center of the screen

	    // Create a new PointerInput (TouchScreen)
	    PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");

	    // Create the sequence of actions
	    Sequence swipe = new Sequence(finger, 0);
	    swipe.addAction(finger.createPointerMove(Duration.ofMillis(0), PointerInput.Origin.viewport(), startVerticalX, startVerticalY));
	    swipe.addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
	    swipe.addAction(finger.createPointerMove(Duration.ofMillis(500), PointerInput.Origin.viewport(), startVerticalX, endVerticalY));  // Swipe down
	    swipe.addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

	    // Perform the swipe action
	    iosdriver.perform(Arrays.asList(swipe));

	    System.out.println("Swipe Down Completed");
	}
