    public void startServer(Map<String, String> objDictionary) {
        String strDeviceAppiumPort = objDictionary.get("strDeviceAppiumPort");
        int port = Integer.parseInt(strDeviceAppiumPort != null ? strDeviceAppiumPort : "4723");

        String logFilePath = System.getProperty("user.dir") + "/appium_full.log";
        System.out.println("Appium logs will be written to: " + logFilePath);
        Reporter.log("Appium logs will be written to: " + logFilePath);

        try {
            // Clean up any previous service
            if (service != null && service.isRunning()) {
                service.stop();
                Thread.sleep(2000);
            }

            AppiumServiceBuilder builder = new AppiumServiceBuilder()
                    .withIPAddress("127.0.0.1")
                    .usingPort(port)
                    .withArgument(GeneralServerFlag.SESSION_OVERRIDE)
                    .withArgument(() -> "--allow-cors")           // ← This is the correct syntax
                    .withArgument(GeneralServerFlag.LOG_LEVEL, "debug")
                    .withLogFile(new File(logFilePath))
                    .withTimeout(Duration.ofSeconds(30));

            service = AppiumDriverLocalService.buildService(builder);
            service.start();

            // Extra buffer so Inspector can reliably connect
            Thread.sleep(5000);

            Reporter.log("Appium server started successfully on port " + port + " (with --allow-cors)");
            System.out.println("✅ Appium server started on http://127.0.0.1:" + port + " with CORS enabled");

        } catch (Exception e) {
            e.printStackTrace();
            Reporter.log("Failed to start Appium server: " + e.getMessage());
            throw new RuntimeException("Appium server failed to start", e);
        }
    }
