	public void stopServer(Map<String, String> objDictionary) {
	    try {
	        // First try graceful stop via the service object
	        if (service != null) {
	            if (service.isRunning()) {
	                service.stop();
	                System.out.println("Appium service stopped gracefully.");
	                Reporter.log("Appium service stopped gracefully.");
	            }
	            service = null;
	        }

	        // Aggressive fallback: kill ALL node processes on the exact port
	        String port = objDictionary.get("strDeviceAppiumPort");
	        if (port != null) {
	            String[] killCommand = {"sh", "-c", "lsof -ti:" + port + " | xargs kill -9"};
	            Runtime.getRuntime().exec(killCommand);
	            System.out.println("Killed any remaining processes on port " + port);
	            Reporter.log("Killed remaining Appium processes on port " + port);
	        }

	        Thread.sleep(3000); // Give OS time to release the port

	    } catch (Exception e) {
	        System.out.println("Error during stopServer: " + e.getMessage());
	        e.printStackTrace();
	    }
	}
